  FRUITS = 'Fruits',
  VEGETABLES = 'Vegetables',
  DAIRY = 'Dairy',
  SNACKS = 'Snacks',
  BAKERY = 'Bakery',
  BEVERAGES = 'Beverages'
}

export interface Product {
  id: string;
  name: string;
  price: number;
  category: Category;
  image: string;
  unit: string;
  description?: string;
  inStock: boolean;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  isThinking?: boolean;
}

export type SortOption = 'featured' | 'price-asc' | 'price-desc' | 'name-asc';

