              <ul className="space-y-2 text-sm text-gray-500">
                <li><a href="#" className="hover:text-emerald-600">Fresh Fruit</a></li>
                <li><a href="#" className="hover:text-emerald-600">Vegetables</a></li>
                <li><a href="#" className="hover:text-emerald-600">Dairy & Eggs</a></li>
                <li><a href="#" className="hover:text-emerald-600">Bakery</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-semibold text-gray-900 mb-4">Support</h4>
              <ul className="space-y-2 text-sm text-gray-500">
                <li><a href="#" className="hover:text-emerald-600">Help Center</a></li>
                <li><a href="#" className="hover:text-emerald-600">Delivery Information</a></li>
                <li><a href="#" className="hover:text-emerald-600">Return Policy</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-semibold text-gray-900 mb-4">Contact</h4>
              <ul className="space-y-2 text-sm text-gray-500">
                <li>support@harisupermarket.com</li>
                <li>+1 (555) 123-4567</li>
              </ul>
            </div>
          </div>
          <div className="border-t border-gray-100 pt-8 text-center">
             <p className="text-gray-400 text-sm">
            © {new Date().getFullYear()} Hari Supermarket. All rights reserved.
          </p>
          </div>
        </div>
      </footer>

      {/* Overlays */}
      <ProductDetailsModal 
        product={selectedProduct}
        isOpen={!!selectedProduct}
        onClose={() => setSelectedProduct(null)}
        onAddToCart={addToCart}
      />

      <CartSidebar
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        items={cartItems}
        onUpdateQuantity={updateQuantity}
        onRemoveItem={removeItem}
      />

      <Assistant 
        isOpen={isAssistantOpen} 
        onClose={() => setIsAssistantOpen(false)} 
      />
    </div>
  );
};

