import React, { useState } from 'react';
import { Plus, Ban, ImageOff } from 'lucide-react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onAddToCart: (product: Product) => void;
  onView: (product: Product) => void;
}

const ProductCard: React.FC<ProductCardProps> = ({ product, onAddToCart, onView }) => {
  const [imageError, setImageError] = useState(false);

  return (
    <div 
      className={`group bg-white rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-all duration-300 overflow-hidden flex flex-col h-full cursor-pointer ${
        !product.inStock ? 'opacity-75' : ''
      }`}
      onClick={() => onView(product)}
    >
      <div className="relative aspect-[4/3] overflow-hidden bg-gray-50">
        {!imageError ? (
          <img
            src={product.image}
            alt={product.name}
            className={`w-full h-full object-cover transform transition-transform duration-500 ${
              product.inStock ? 'group-hover:scale-105' : 'grayscale'
            }`}
            loading="lazy"
            onError={() => setImageError(true)}
          />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center text-gray-400 bg-gray-100 p-4 text-center">
            <ImageOff className="w-8 h-8 mb-2 opacity-50" />
            <span className="text-xs font-medium">{product.name}</span>
          </div>
        )}

        {!product.inStock && (
          <div className="absolute inset-0 bg-black/10 flex items-center justify-center">
            <span className="bg-gray-900/80 text-white text-xs font-bold px-3 py-1 rounded-full backdrop-blur-sm">
              Out of Stock
            </span>
          </div>
        )}

        {product.inStock && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              onAddToCart(product);
            }}
            className="absolute bottom-3 right-3 bg-white text-emerald-600 p-2 rounded-full shadow-lg hover:bg-emerald-600 hover:text-white transition-all transform translate-y-2 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 focus:opacity-100 focus:translate-y-0 z-10"
            aria-label={`Add ${product.name} to cart`}
          >
            <Plus className="w-5 h-5" />
          </button>
        )}
      </div>
      <div className="p-4 flex flex-col flex-grow">
        <div className="flex justify-between items-start mb-1">
          <p className="text-xs font-semibold text-emerald-600 uppercase tracking-wide">
            {product.category}
          </p>
          <span className="text-sm font-bold text-gray-900">
            ${product.price.toFixed(2)}
          </span>
        </div>
        <h3 className={`font-semibold mb-1 leading-tight ${product.inStock ? 'text-gray-800' : 'text-gray-500'}`}>
          {product.name}
        </h3>
        <p className="text-xs text-gray-500 mb-4 line-clamp-2">{product.description}</p>

        <div className="mt-auto pt-2 border-t border-gray-50 flex items-center justify-between">
           <span className="text-xs text-gray-400">Per {product.unit}</span>
           {product.inStock ? (
             <button 
               onClick={(e) => {
                 e.stopPropagation();
                 onAddToCart(product);
               }}
               className="text-sm font-medium text-emerald-600 hover:text-emerald-700 md:hidden"
             >
               Add to Cart
             </button>
           ) : (
             <span className="text-xs font-medium text-red-500 flex items-center gap-1">
               <Ban className="w-3 h-3" />
               Unavailable
             </span>
           )}
        </div>
      </div>
    </div>
  );
};

