import React, { useState, useMemo, useEffect } from 'react';
import { ShoppingCart, Search, Sparkles, Clock, SlidersHorizontal, ArrowUpDown, Sun, Moon } from 'lucide-react';
import ProductCard from './components/ProductCard';
import ProductDetailsModal from './components/ProductDetailsModal';
import CartSidebar from './components/CartSidebar';
import Assistant from './components/Assistant';
import { MOCK_PRODUCTS, CATEGORIES } from './constants';
import { Product, CartItem, Category, SortOption } from './types';

const App: React.FC = () => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isAssistantOpen, setIsAssistantOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // New state for sorting and filtering
  const [sortBy, setSortBy] = useState<SortOption>('featured');
  const [showInStockOnly, setShowInStockOnly] = useState(false);

  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);

  // Initialize theme
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      setIsDarkMode(false);
      document.documentElement.classList.remove('dark');
    }
  }, []);

  const toggleTheme = () => {
    setIsDarkMode(prev => {
      const newMode = !prev;
      if (newMode) {
        document.documentElement.classList.add('dark');
        localStorage.setItem('theme', 'dark');
      } else {
        document.documentElement.classList.remove('dark');
        localStorage.setItem('theme', 'light');
      }
      return newMode;
    });
  };

  // Handle scroll effect for header
  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Load recently viewed from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('hari_supermarket_recently_viewed');
    if (saved) {
      try {
        setRecentlyViewedIds(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse recently viewed', e);
      }
    }
  }, []);

  const filteredProducts = useMemo(() => {
    let result = MOCK_PRODUCTS.filter((product) => {
      const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
      const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           product.category.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesStock = !showInStockOnly || product.inStock;

      return matchesCategory && matchesSearch && matchesStock;
    });

    // Sorting logic
    switch (sortBy) {
      case 'price-asc':
        result.sort((a, b) => a.price - b.price);
        break;
      case 'price-desc':
        result.sort((a, b) => b.price - a.price);
        break;
      case 'name-asc':
        result.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case 'featured':
      default:
        // Default ID sort for stability, or could be a 'featured' flag
        result.sort((a, b) => Number(a.id) - Number(b.id));
        break;
    }

    return result;
  }, [selectedCategory, searchQuery, sortBy, showInStockOnly]);

  const recentlyViewedProducts = useMemo(() => {
    return recentlyViewedIds
      .map(id => MOCK_PRODUCTS.find(p => p.id === id))
      .filter((p): p is Product => !!p);
  }, [recentlyViewedIds]);

  const addToCart = (product: Product) => {
    if (!product.inStock) return;

    setCartItems((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const updateQuantity = (id: string, delta: number) => {
    setCartItems((prev) =>
      prev.map((item) => {
        if (item.id === id) {
          return { ...item, quantity: Math.max(1, item.quantity + delta) };
        }
        return item;
      })
    );
  };

  const removeItem = (id: string) => {
    setCartItems((prev) => prev.filter((item) => item.id !== id));
  };

  const handleViewProduct = (product: Product) => {
    setSelectedProduct(product);

    setRecentlyViewedIds(prev => {
      const filtered = prev.filter(id => id !== product.id);
      const newIds = [product.id, ...filtered].slice(0, 4);
      localStorage.setItem('hari_supermarket_recently_viewed', JSON.stringify(newIds));
      return newIds;
    });
  };

  const cartCount = cartItems.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-950 flex flex-col transition-colors duration-300">
      {/* Header */}
      <header
        className={`sticky top-0 z-30 transition-all duration-300 ${
          scrolled 
            ? 'bg-white/90 dark:bg-gray-900/90 backdrop-blur-md shadow-sm py-3' 
            : 'bg-white dark:bg-gray-900 py-5 border-b border-gray-100 dark:border-gray-800'
        }`}
      >
        <div className="container mx-auto px-4 md:px-6">
          <div className="flex items-center justify-between gap-4">
            {/* Logo */}
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 md:w-10 md:h-10 bg-emerald-600 rounded-lg flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-emerald-600/20">
                H
              </div>
              <h1 className="text-lg md:text-2xl font-bold text-gray-900 dark:text-white tracking-tight hidden sm:block">
                Hari <span className="text-emerald-600">Supermarket</span>
              </h1>
            </div>

            {/* Search Bar */}
            <div className="flex-1 max-w-xl relative">
              <input
                type="text"
                placeholder="Search fresh groceries..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-gray-100 dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-750 border border-transparent focus:border-emerald-500 focus:bg-white dark:focus:bg-gray-800 rounded-full py-2.5 pl-12 pr-4 outline-none transition-all text-sm md:text-base placeholder-gray-400 dark:placeholder-gray-500 text-gray-900 dark:text-gray-100"
              />
              <Search className="w-5 h-5 text-gray-400 dark:text-gray-500 absolute left-4 top-1/2 transform -translate-y-1/2" />
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 md:gap-4">
              <button
                onClick={toggleTheme}
                className="p-2 md:p-3 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors text-gray-700 dark:text-gray-300"
                aria-label="Toggle Theme"
              >
                {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
              </button>

              <button
                onClick={() => setIsAssistantOpen(true)}
                className="p-2 md:px-4 md:py-2 text-emerald-600 dark:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/30 rounded-full transition-colors flex items-center gap-2"
                title="Ask Assistant"
              >
                <Sparkles className="w-5 h-5" />
                <span className="hidden md:inline font-medium text-sm">Ask Hari</span>
              </button>

              <button
                onClick={() => setIsCartOpen(true)}
                className="relative p-2 md:p-3 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"
              >
                <ShoppingCart className="w-6 h-6 text-gray-700 dark:text-gray-300" />
                {cartCount > 0 && (
                  <span className="absolute top-0 right-0 md:top-1 md:right-1 bg-red-500 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border-2 border-white dark:border-gray-900">
                    {cartCount}
                  </span>
                )}
              </button>
            </div>
          </div>

          {/* Category Pills (Mobile & Desktop) */}
          <div className="mt-4 flex gap-2 overflow-x-auto pb-2 no-scrollbar">
            <button
              onClick={() => setSelectedCategory('All')}
              className={`whitespace-nowrap px-4 py-1.5 rounded-full text-sm font-medium transition-all ${
                selectedCategory === 'All'
                  ? 'bg-emerald-600 text-white shadow-md shadow-emerald-200 dark:shadow-none'
                  : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-700 hover:border-emerald-200 dark:hover:border-emerald-800 hover:text-emerald-600 dark:hover:text-emerald-500'
              }`}
            >
              All
            </button>
            {CATEGORIES.map((cat) => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`whitespace-nowrap px-4 py-1.5 rounded-full text-sm font-medium transition-all ${
                  selectedCategory === cat
                    ? 'bg-emerald-600 text-white shadow-md shadow-emerald-200 dark:shadow-none'
                    : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-700 hover:border-emerald-200 dark:hover:border-emerald-800 hover:text-emerald-600 dark:hover:text-emerald-500'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-4 md:px-6 py-8">
        {/* Page Title & Controls */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4 mb-8">
          <div>
            <h2 className="text-2xl md:text-3xl font-bold text-gray-900 dark:text-white tracking-tight">
              {selectedCategory === 'All' ? 'Fresh & Featured' : selectedCategory}
            </h2>
            <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm md:text-base">
              Hand-picked quality products for you
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
            {/* Filter Toggle */}
            <label className="flex items-center gap-2 cursor-pointer bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 px-3 py-2 rounded-lg hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors select-none">
              <input 
                type="checkbox" 
                checked={showInStockOnly} 
                onChange={() => setShowInStockOnly(!showInStockOnly)}
                className="w-4 h-4 text-emerald-600 rounded border-gray-300 dark:border-gray-600 focus:ring-emerald-500 dark:focus:ring-emerald-500 dark:bg-gray-700"
              />
              <span className="text-sm font-medium text-gray-700 dark:text-gray-300">In Stock Only</span>
            </label>

            {/* Sort Dropdown */}
            <div className="relative group">
              <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
                <ArrowUpDown className="w-4 h-4 text-gray-400 dark:text-gray-500" />
              </div>
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value as SortOption)}
                className="appearance-none bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 text-sm font-medium rounded-lg pl-9 pr-8 py-2 focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:border-transparent hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors cursor-pointer"
              >
                <option value="featured">Featured</option>
                <option value="price-asc">Price: Low to High</option>
                <option value="price-desc">Price: High to Low</option>
                <option value="name-asc">Name: A-Z</option>
              </select>
            </div>
          </div>
        </div>

        {/* Product Grid */}
        {filteredProducts.length > 0 ? (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
            {filteredProducts.map((product) => (
              <ProductCard
                key={product.id}
                product={product}
                onAddToCart={addToCart}
                onView={handleViewProduct}
              />
            ))}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-20 text-center bg-white dark:bg-gray-900 rounded-2xl border border-dashed border-gray-200 dark:border-gray-800">
            <div className="w-16 h-16 bg-gray-50 dark:bg-gray-800 rounded-full flex items-center justify-center mb-4">
              <SlidersHorizontal className="w-8 h-8 text-gray-400 dark:text-gray-500" />
            </div>
            <h3 className="text-lg font-semibold text-gray-800 dark:text-gray-200">No items match your criteria</h3>
            <p className="text-gray-500 dark:text-gray-400 max-w-xs mx-auto mt-2 mb-6">
              Try adjusting your filters or search terms to find what you're looking for.
            </p>
            <button 
              onClick={() => { 
                setSearchQuery(''); 
                setSelectedCategory('All'); 
                setShowInStockOnly(false);
                setSortBy('featured');
              }}
              className="text-emerald-600 dark:text-emerald-500 font-medium hover:underline bg-emerald-50 dark:bg-emerald-900/20 px-6 py-2 rounded-full transition-colors"
            >
              Clear all filters
            </button>
          </div>
        )}

        {/* Recently Viewed Section */}
        {recentlyViewedProducts.length > 0 && (
          <div className="mt-16 border-t border-gray-100 dark:border-gray-800 pt-10">
            <div className="flex items-center gap-2 mb-6">
              <Clock className="w-5 h-5 text-emerald-600 dark:text-emerald-500" />
              <h3 className="text-xl font-bold text-gray-800 dark:text-gray-100">Recently Viewed</h3>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6">
              {recentlyViewedProducts.map(product => (
                <ProductCard
                  key={`recent-${product.id}`}
                  product={product}
                  onAddToCart={addToCart}
                  onView={handleViewProduct}
                />
              ))}
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-800 py-12 mt-auto">
        <div className="container mx-auto px-4">
          <div className="grid md:grid-cols-4 gap-8 mb-8">
            <div className="col-span-1 md:col-span-1">
              <div className="flex items-center gap-2 mb-4">
                <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center text-white font-bold">H</div>
                <span className="font-bold text-gray-900 dark:text-white text-lg">Hari Supermarket</span>
              </div>
              <p className="text-gray-500 dark:text-gray-400 text-sm">Providing fresh, organic, and locally sourced groceries since 2024.</p>
            </div>
            <div>
              <h4 className="font-semibold text-gray-900 dark:text-gray-100 mb-4">Shop</h4>
              <ul className="space-y-2 text-sm text-gray-500 dark:text-gray-400">
                <li><a href="#" className="hover:text-emerald-600 dark:hover:text-emerald-500">Fresh Fruit</a></li>
                <li><a href="#" className="hover:text-emerald-600 dark:hover:text-emerald-500">Vegetables</a></li>
                <li><a href="#" className="hover:text-emerald-600 dark:hover:text-emerald-500">Dairy & Eggs</a></li>
                <li><a href="#" className="hover:text-emerald-600 dark:hover:text-emerald-500">Bakery</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-semibold text-gray-900 dark:text-gray-100 mb-4">Support</h4>
              <ul className="space-y-2 text-sm text-gray-500 dark:text-gray-400">
                <li><a href="#" className="hover:text-emerald-600 dark:hover:text-emerald-500">Help Center</a></li>
                <li><a href="#" className="hover:text-emerald-600 dark:hover:text-emerald-500">Delivery Information</a></li>
                <li><a href="#" className="hover:text-emerald-600 dark:hover:text-emerald-500">Return Policy</a></li>
              </ul>
            </div>
