import React, { useState } from 'react';
import { Plus, Ban, ImageOff, Star, Eye } from 'lucide-react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onAddToCart: (product: Product) => void;
  onView: (product: Product) => void;
}

const ProductCard: React.FC<ProductCardProps> = ({ product, onAddToCart, onView }) => {
  const [imageError, setImageError] = useState(false);

  return (
    <div 
      className={`group bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 hover:border-emerald-200 dark:hover:border-emerald-800 shadow-sm hover:shadow-lg transition-all duration-300 overflow-hidden flex flex-col h-full cursor-pointer relative`}
      onClick={() => onView(product)}
    >
      {/* Badges */}
      {product.inStock && (
        <div className="absolute top-3 left-3 z-10">
          <span className="bg-green-500 text-white text-[10px] font-bold px-2 py-1 rounded">
             SALE
          </span>
        </div>
      )}

      {/* Action Overlay */}
      <div className="absolute top-3 right-3 z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col gap-2">
         <button className="bg-white dark:bg-gray-700 p-2 rounded-full shadow-md text-gray-500 hover:text-emerald-600 transition-colors">
            <Eye className="w-4 h-4" />
         </button>
      </div>

      <div className="relative p-4 pb-0 h-48 overflow-hidden bg-white dark:bg-gray-800 flex items-center justify-center">
        {!imageError ? (
          <img
            src={product.image}
            alt={product.name}
            className={`w-full h-full object-contain transform transition-transform duration-500 ${
              product.inStock ? 'group-hover:scale-110' : 'grayscale opacity-50'
            }`}
            loading="lazy"
            onError={() => setImageError(true)}
          />
        ) : (
          <div className="flex flex-col items-center justify-center text-gray-300 dark:text-gray-600">
            <ImageOff className="w-10 h-10 mb-2 opacity-50" />
            <span className="text-[10px]">No Image</span>
          </div>
        )}

        {!product.inStock && (
          <div className="absolute inset-0 bg-white/50 dark:bg-black/50 flex items-center justify-center backdrop-blur-[1px]">
            <div className="bg-gray-900 text-white text-xs font-bold px-3 py-1 rounded-full">
              Out of Stock
            </div>
          </div>
        )}
      </div>

      <div className="p-4 flex flex-col flex-grow">
        <div className="mb-2">
           <span className="text-xs text-gray-400 dark:text-gray-500">{product.category}</span>
           <h3 className={`font-bold text-gray-800 dark:text-gray-100 leading-tight mb-1 truncate ${!product.inStock && 'text-gray-400'}`}>
            {product.name}
           </h3>
           <div className="flex items-center gap-1">
              <div className="flex text-yellow-400">
                 <Star className="w-3 h-3 fill-current" />
                 <Star className="w-3 h-3 fill-current" />
                 <Star className="w-3 h-3 fill-current" />
                 <Star className="w-3 h-3 fill-current" />
                 <Star className="w-3 h-3 text-gray-300" />
              </div>
              <span className="text-[10px] text-gray-400">(4.0)</span>
           </div>
        </div>

        <div className="mt-auto flex items-center justify-between pt-3 border-t border-gray-50 dark:border-gray-700/50">
           <div>
              <div className="flex items-baseline gap-1">
                 <span className="text-lg font-bold text-emerald-700 dark:text-emerald-400">
                    ${product.price.toFixed(2)}
                 </span>
                 <span className="text-xs text-gray-400 line-through">
                    ${(product.price * 1.2).toFixed(2)}
                 </span>
              </div>
           </div>

           {product.inStock ? (
             <button 
               onClick={(e) => {
                 e.stopPropagation();
                 onAddToCart(product);
               }}
               className="bg-emerald-50 dark:bg-emerald-900/30 hover:bg-emerald-600 dark:hover:bg-emerald-500 text-emerald-700 dark:text-emerald-400 hover:text-white rounded-full p-2 transition-all font-bold flex items-center gap-1 group/btn"
             >
               <span className="text-xs px-1 hidden sm:block">Add</span>
               <Plus className="w-4 h-4" />
             </button>
           ) : (
             <button disabled className="bg-gray-100 dark:bg-gray-700 text-gray-400 rounded-full p-2 cursor-not-allowed">
               <Ban className="w-4 h-4" />
             </button>
           )}
        </div>
      </div>
    </div>
  );
};

export default ProductCard;

import React from 'react';
import { X, Minus, Plus, ShoppingBag, Trash2, ArrowRight } from 'lucide-react';
import { CartItem } from '../types';

interface CartSidebarProps {
  isOpen: boolean;
  onClose: () => void;
  items: CartItem[];
  onUpdateQuantity: (id: string, delta: number) => void;
  onRemoveItem: (id: string) => void;
}

const CartSidebar: React.FC<CartSidebarProps> = ({
  isOpen,
  onClose,
  items,
  onUpdateQuantity,
  onRemoveItem
}) => {
  const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);

  return (
    <>
      {/* Backdrop */}
      <div
        className={`fixed inset-0 bg-black/40 dark:bg-black/70 backdrop-blur-sm z-50 transition-opacity duration-300 ${
          isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        }`}
        onClick={onClose}
      />

      {/* Drawer */}
      <div
        className={`fixed inset-y-0 right-0 z-[60] w-full sm:w-[450px] bg-white dark:bg-gray-900 shadow-2xl transform transition-transform duration-300 ease-in-out ${
          isOpen ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        <div className="flex flex-col h-full">
          <div className="p-6 border-b border-gray-100 dark:border-gray-800 flex justify-between items-center bg-[#155e37]">
            <h2 className="text-xl font-bold text-white flex items-center gap-3">
              <ShoppingBag className="w-6 h-6" />
              Shopping Cart <span className="text-sm font-normal text-emerald-200">({items.length} items)</span>
            </h2>
            <button
              onClick={onClose}
              className="p-2 bg-white/10 hover:bg-white/20 rounded-full transition-colors text-white"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {items.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center text-gray-400 dark:text-gray-500 space-y-6">
                <div className="w-24 h-24 bg-gray-50 dark:bg-gray-800 rounded-full flex items-center justify-center">
                    <ShoppingBag className="w-10 h-10 opacity-30" />
                </div>
                <div>
                    <p className="text-lg font-semibold text-gray-800 dark:text-gray-200">Your cart is empty</p>
                    <p className="text-sm">Looks like you haven't added anything yet.</p>
                </div>
                <button 
                  onClick={onClose}
                  className="px-8 py-3 bg-[#155e37] text-white rounded-xl font-bold text-sm hover:bg-emerald-800 transition-colors shadow-lg shadow-emerald-900/20"
                >
                  Start Shopping
                </button>
              </div>
            ) : (
              items.map((item) => (
                <div key={item.id} className="flex gap-4 p-4 rounded-2xl bg-gray-50 dark:bg-gray-800/50 border border-gray-100 dark:border-gray-800">
                  <div className="w-20 h-20 bg-white dark:bg-gray-700 rounded-xl overflow-hidden flex-shrink-0 border border-gray-100 dark:border-gray-600 p-2">
                    <img src={item.image} alt={item.name} className="w-full h-full object-contain" />
                  </div>
                  <div className="flex-1 flex flex-col justify-between">
                    <div className="flex justify-between items-start">
                        <div>
                           <h3 className="font-bold text-gray-800 dark:text-gray-100">{item.name}</h3>
                           <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">${item.price.toFixed(2)} / {item.unit}</p>
                        </div>
                        <button 
                            onClick={() => onRemoveItem(item.id)}
                            className="text-gray-400 hover:text-red-500 transition-colors p-1"
                        >
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                    <div className="flex items-center justify-between mt-3">
                      <div className="flex items-center gap-3 bg-white dark:bg-gray-700 rounded-lg p-1 border border-gray-200 dark:border-gray-600 shadow-sm">
                        <button
                          onClick={() => onUpdateQuantity(item.id, -1)}
                          className="w-6 h-6 flex items-center justify-center bg-gray-100 dark:bg-gray-600 rounded hover:bg-emerald-100 dark:hover:bg-emerald-900/50 hover:text-emerald-700 dark:hover:text-emerald-400 transition-colors disabled:opacity-50"
                          disabled={item.quantity <= 1}
                        >
                          <Minus className="w-3 h-3" />
