      >
        <div className="container mx-auto px-4 md:px-6">
          <div className="flex items-center justify-between gap-4 md:gap-8">
            {/* Logo */}
            <div className="flex items-center gap-2 flex-shrink-0 cursor-pointer" onClick={() => setSelectedCategory('All')}>
              <div className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center backdrop-blur-sm border border-white/20">
                <span className="text-2xl">🛍️</span>
              </div>
              <div className="flex flex-col">
                <h1 className="text-2xl font-bold text-white tracking-tight leading-none">
                  H Mart
                </h1>
                <span className="text-[10px] text-emerald-200 uppercase tracking-widest font-semibold">Grocery Store</span>
              </div>
            </div>

            {/* Search Bar - Rectangular with yellow button */}
            <div className="flex-1 max-w-3xl hidden md:flex items-center relative">
               <div className="w-full flex rounded-lg overflow-hidden bg-white shadow-lg">
                  <div className="flex items-center px-4 bg-gray-50 border-r border-gray-200 text-gray-500 text-sm font-medium cursor-pointer hover:bg-gray-100 transition-colors">
                     All Categories <ChevronDown className="w-4 h-4 ml-2" />
                  </div>
                  <input
                    type="text"
                    placeholder="Search for products, brands and more..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="flex-1 px-4 py-3 outline-none text-gray-700 placeholder-gray-400"
                  />
                  <button className="bg-yellow-400 hover:bg-yellow-500 text-gray-900 w-12 flex items-center justify-center transition-colors">
                    <Search className="w-5 h-5" />
                  </button>
               </div>
            </div>

            {/* Mobile Search Icon */}
            <button className="md:hidden text-white p-2">
               <Search className="w-6 h-6" />
            </button>

            {/* Actions */}
            <div className="flex items-center gap-2 md:gap-6 text-white">
              <button
                onClick={toggleTheme}
                className="p-2 hover:bg-white/10 rounded-full transition-colors"
              >
                 {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
              </button>

              <div className="hidden md:flex items-center gap-3 cursor-pointer hover:bg-white/10 p-2 rounded-lg transition-colors">
                 <User className="w-6 h-6" />
                 <div className="flex flex-col text-xs">
                    <span className="text-emerald-200">Sign In</span>
                    <span className="font-bold">Account</span>
                 </div>
              </div>

              <button
                onClick={() => setIsCartOpen(true)}
                className="relative p-2 md:pr-4 flex items-center gap-3 group"
              >
                <div className="relative">
                  <ShoppingCart className="w-7 h-7" />
                  {cartCount > 0 && (
                    <span className="absolute -top-2 -right-2 bg-yellow-400 text-gray-900 text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border-2 border-[#155e37]">
                      {cartCount}
                    </span>
                  )}
                </div>
                <div className="hidden md:flex flex-col text-xs text-left">
                    <span className="text-emerald-200">Total</span>
                    <span className="font-bold text-white">$0.00</span>
                </div>
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Secondary Nav / Category Strip (Mobile scrollable) */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 shadow-sm">
         <div className="container mx-auto px-4 overflow-x-auto no-scrollbar">
            <div className="flex items-center gap-8 py-3 text-sm font-medium text-gray-600 dark:text-gray-300 whitespace-nowrap">
               <button 
                  onClick={() => setSelectedCategory('All')}
                  className={`flex items-center gap-2 hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors ${selectedCategory === 'All' ? 'text-emerald-600 dark:text-emerald-400 font-bold' : ''}`}
                >
                  <Menu className="w-4 h-4" /> All Categories
               </button>
               {CATEGORIES.map(cat => (
                 <button 
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors ${selectedCategory === cat ? 'text-emerald-600 dark:text-emerald-400 font-bold' : ''}`}
                 >
                    {cat}
                 </button>
               ))}
               <div className="h-4 w-px bg-gray-300 dark:bg-gray-600 mx-2"></div>
               <button className="text-emerald-600 dark:text-emerald-400 font-bold flex items-center gap-2" onClick={() => setIsAssistantOpen(true)}>
                  <Sparkles className="w-4 h-4" /> AI Assistant
               </button>
            </div>
         </div>
      </div>

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-4 md:px-6 py-8">

        {/* Only show Hero on Home/All */}
        {selectedCategory === 'All' && !searchQuery && <HeroSection />}

        {/* Page Title & Controls */}
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 mb-8 border-b border-gray-100 dark:border-gray-800 pb-4">
