             <div className="flex items-center gap-2 mb-1">
                <span className="h-6 w-1 bg-emerald-600 rounded-full"></span>
                <h2 className="text-2xl font-bold text-gray-900 dark:text-white tracking-tight">
                {selectedCategory === 'All' ? (searchQuery ? `Search: "${searchQuery}"` : 'Best Selling Products') : selectedCategory}
                </h2>
             </div>
             {selectedCategory === 'All' && !searchQuery && (
                <p className="text-gray-500 dark:text-gray-400 text-sm ml-3">
