                </p>
             )}
          </div>

          <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
            {/* Filter Toggle */}
            <label className="flex items-center gap-2 cursor-pointer bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 px-3 py-2 rounded-lg hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors select-none">
              <input 
                type="checkbox" 
                checked={showInStockOnly} 
                onChange={() => setShowInStockOnly(!showInStockOnly)}
