              />
              <span className="text-sm font-medium text-gray-700 dark:text-gray-300">In Stock</span>
            </label>

            {/* Sort Dropdown */}
            <div className="relative group">
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value as SortOption)}
