                 <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center text-gray-600 dark:text-gray-400 hover:bg-[#155e37] hover:text-white transition-colors cursor-pointer">TW</div>
                 <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center text-gray-600 dark:text-gray-400 hover:bg-[#155e37] hover:text-white transition-colors cursor-pointer">IG</div>
              </div>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 dark:text-gray-100 mb-6 text-lg">Shop Categories</h4>
              <ul className="space-y-3 text-gray-500 dark:text-gray-400">
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Fresh Fruit</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Vegetables</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Dairy & Eggs</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Bakery</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Meat & Seafood</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 dark:text-gray-100 mb-6 text-lg">Customer Service</h4>
