                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Contact Us</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Privacy Policy</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Terms & Conditions</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">FAQ</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 dark:text-gray-100 mb-6 text-lg">Contact Us</h4>
              <ul className="space-y-4 text-gray-500 dark:text-gray-400">
                <li className="flex items-start gap-3">
                    <span className="text-xl">📍</span>
                    <span>1234 Grocery St, Market City, ST 12345</span>
                </li>
                <li className="flex items-center gap-3">
                    <span className="text-xl">📞</span>
                    <span>+1 (555) 123-4567</span>
                </li>
                <li className="flex items-center gap-3">
                    <span className="text-xl">✉️</span>
                    <span>support@hmart.com</span>
                </li>
              </ul>
            </div>
          </div>
          <div className="border-t border-gray-100 dark:border-gray-800 pt-8 flex flex-col md:flex-row justify-between items-center gap-4">
             <p className="text-gray-400 dark:text-gray-500 text-sm">
                © {new Date().getFullYear()} H Mart. All rights reserved.
            </p>
            <div className="flex gap-4">
               <div className="h-8 w-12 bg-gray-200 dark:bg-gray-700 rounded"></div>
               <div className="h-8 w-12 bg-gray-200 dark:bg-gray-700 rounded"></div>
               <div className="h-8 w-12 bg-gray-200 dark:bg-gray-700 rounded"></div>
            </div>
          </div>
        </div>
      </footer>

      {/* Overlays */}
      <ProductDetailsModal 
        product={selectedProduct}
        isOpen={!!selectedProduct}
        onClose={() => setSelectedProduct(null)}
        onAddToCart={addToCart}
      />

      <CartSidebar
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        items={cartItems}
        onUpdateQuantity={updateQuantity}
        onRemoveItem={removeItem}
      />

      <Assistant 
        isOpen={isAssistantOpen} 
        onClose={() => setIsAssistantOpen(false)} 
      />
    </div>
  );
};

