export default HeroSection;

import React, { useState, useMemo, useEffect } from 'react';
import { ShoppingCart, Search, Sparkles, Clock, SlidersHorizontal, ArrowUpDown, Sun, Moon, Menu, User, ChevronDown, LayoutGrid } from 'lucide-react';
import ProductCard from './components/ProductCard';
import ProductDetailsModal from './components/ProductDetailsModal';
import CartSidebar from './components/CartSidebar';
import Assistant from './components/Assistant';
import HeroSection from './components/HeroSection';
import FeaturesStrip from './components/FeaturesStrip';
import { MOCK_PRODUCTS, CATEGORIES } from './constants';
import { Product, CartItem, Category, SortOption } from './types';

const App: React.FC = () => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isAssistantOpen, setIsAssistantOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // New state for sorting and filtering
  const [sortBy, setSortBy] = useState<SortOption>('featured');
  const [showInStockOnly, setShowInStockOnly] = useState(false);

  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);

  // Initialize theme
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      setIsDarkMode(false);
      document.documentElement.classList.remove('dark');
    }
  }, []);

  const toggleTheme = () => {
    setIsDarkMode(prev => {
      const newMode = !prev;
      if (newMode) {
        document.documentElement.classList.add('dark');
        localStorage.setItem('theme', 'dark');
      } else {
        document.documentElement.classList.remove('dark');
        localStorage.setItem('theme', 'light');
      }
      return newMode;
    });
  };

  // Handle scroll effect for header
  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Load recently viewed from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('hari_supermarket_recently_viewed');
    if (saved) {
      try {
        setRecentlyViewedIds(JSON.parse(saved));
      } catch (e) {
        console.error('Failed to parse recently viewed', e);
      }
    }
  }, []);

  const filteredProducts = useMemo(() => {
    let result = MOCK_PRODUCTS.filter((product) => {
      const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
      const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           product.category.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesStock = !showInStockOnly || product.inStock;

      return matchesCategory && matchesSearch && matchesStock;
    });

    // Sorting logic
    switch (sortBy) {
      case 'price-asc':
        result.sort((a, b) => a.price - b.price);
        break;
      case 'price-desc':
        result.sort((a, b) => b.price - a.price);
        break;
      case 'name-asc':
        result.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case 'featured':
      default:
        // Default ID sort for stability
        result.sort((a, b) => Number(a.id) - Number(b.id));
        break;
    }

    return result;
  }, [selectedCategory, searchQuery, sortBy, showInStockOnly]);

  const recentlyViewedProducts = useMemo(() => {
    return recentlyViewedIds
      .map(id => MOCK_PRODUCTS.find(p => p.id === id))
      .filter((p): p is Product => !!p);
  }, [recentlyViewedIds]);

  const addToCart = (product: Product) => {
    if (!product.inStock) return;

    setCartItems((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const updateQuantity = (id: string, delta: number) => {
    setCartItems((prev) =>
      prev.map((item) => {
        if (item.id === id) {
          return { ...item, quantity: Math.max(1, item.quantity + delta) };
        }
        return item;
      })
    );
  };

  const removeItem = (id: string) => {
    setCartItems((prev) => prev.filter((item) => item.id !== id));
  };

  const handleViewProduct = (product: Product) => {
    setSelectedProduct(product);

    setRecentlyViewedIds(prev => {
      const filtered = prev.filter(id => id !== product.id);
      const newIds = [product.id, ...filtered].slice(0, 4);
      localStorage.setItem('hari_supermarket_recently_viewed', JSON.stringify(newIds));
      return newIds;
    });
  };

  const cartCount = cartItems.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-950 flex flex-col transition-colors duration-300 font-sans">
      {/* Header - H Mart Style */}
      <header
        className={`sticky top-0 z-40 transition-all duration-300 ${
          scrolled 
            ? 'shadow-md py-2 bg-[#155e37] dark:bg-gray-900' 
            : 'py-3 bg-[#155e37] dark:bg-gray-900'
        }`}
      >
        <div className="container mx-auto px-4 md:px-6">
          <div className="flex items-center justify-between gap-4 md:gap-8">
            {/* Logo */}
            <div className="flex items-center gap-2 flex-shrink-0 cursor-pointer group" onClick={() => setSelectedCategory('All')}>
              <div className="w-9 h-9 bg-white/10 rounded-xl flex items-center justify-center backdrop-blur-sm border border-white/20 group-hover:bg-white/20 transition-colors">
                <span className="text-xl">🛍️</span>
              </div>
              <div className="flex flex-col">
                <h1 className="text-xl font-bold text-white tracking-tight leading-none group-hover:text-emerald-200 transition-colors">
                  H Mart
                </h1>
              </div>
            </div>

            {/* Search Bar - Cleaned up */}
            <div className="flex-1 max-w-2xl hidden md:flex items-center relative">
               <div className="w-full flex rounded-full overflow-hidden bg-white shadow-lg border-2 border-transparent focus-within:border-yellow-400 transition-colors">
                  <input
                    type="text"
                    placeholder="Search for fresh fruits, vegetables & more..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="flex-1 px-6 py-2.5 outline-none text-gray-700 placeholder-gray-400 text-sm"
                  />
                  <button className="bg-yellow-400 hover:bg-yellow-500 text-gray-900 w-12 flex items-center justify-center transition-colors">
                    <Search className="w-5 h-5" />
                  </button>
               </div>
            </div>

            {/* Mobile Search Icon */}
            <button className="md:hidden text-white p-2">
               <Search className="w-6 h-6" />
            </button>

            {/* Actions */}
            <div className="flex items-center gap-2 md:gap-5 text-white">
              <button
                onClick={toggleTheme}
                className="p-2 hover:bg-white/10 rounded-full transition-colors"
              >
                 {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
              </button>

              <div className="hidden md:flex items-center gap-3 cursor-pointer hover:bg-white/10 p-1.5 px-3 rounded-lg transition-colors">
                 <User className="w-5 h-5" />
                 <span className="font-medium text-sm">Account</span>
              </div>

              <button
                onClick={() => setIsCartOpen(true)}
                className="relative p-2 flex items-center gap-3 group"
              >
                <div className="relative">
                  <ShoppingCart className="w-6 h-6" />
                  {cartCount > 0 && (
                    <span className="absolute -top-1.5 -right-1.5 bg-yellow-400 text-gray-900 text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full shadow-sm">
                      {cartCount}
                    </span>
                  )}
                </div>
                <span className="hidden md:block font-bold text-sm group-hover:text-yellow-400 transition-colors">Cart</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Secondary Nav / Category Strip (Mobile scrollable) */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 shadow-sm">
         <div className="container mx-auto px-4 overflow-x-auto no-scrollbar">
            <div className="flex items-center gap-8 py-3 text-sm font-medium text-gray-600 dark:text-gray-300 whitespace-nowrap">
               <button 
                  onClick={() => setSelectedCategory('All')}
                  className={`flex items-center gap-2 hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors ${selectedCategory === 'All' ? 'text-emerald-600 dark:text-emerald-400 font-bold' : ''}`}
                >
                  <LayoutGrid className="w-4 h-4" /> All
               </button>
               {CATEGORIES.map(cat => (
                 <button 
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors ${selectedCategory === cat ? 'text-emerald-600 dark:text-emerald-400 font-bold' : ''}`}
                 >
                    {cat}
                 </button>
               ))}
               <div className="h-4 w-px bg-gray-300 dark:bg-gray-600 mx-2"></div>
               <button className="text-emerald-600 dark:text-emerald-400 font-bold flex items-center gap-2" onClick={() => setIsAssistantOpen(true)}>
                  <Sparkles className="w-4 h-4" /> AI Assistant
               </button>
            </div>
         </div>
      </div>

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-4 md:px-6 py-8">

        {/* Only show Hero on Home/All */}
        {selectedCategory === 'All' && !searchQuery && <HeroSection />}

        {/* Section Divider & Title */}
        <div className={`flex flex-col md:flex-row justify-between items-end gap-4 mb-8 ${selectedCategory === 'All' && !searchQuery ? 'mt-12' : ''}`}>
          <div className="w-full">
             {/* Divider for visual separation */}
             {selectedCategory === 'All' && !searchQuery && (
                <div className="flex items-center gap-4 mb-6">
                    <div className="h-px bg-emerald-200 dark:bg-emerald-900 flex-1"></div>
                    <div className="text-emerald-600 dark:text-emerald-400 font-bold text-sm tracking-widest uppercase flex items-center gap-2">
                        <Sparkles className="w-4 h-4" /> Our Selection
                    </div>
                    <div className="h-px bg-emerald-200 dark:bg-emerald-900 flex-1"></div>
                </div>
             )}

             <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white tracking-tight">
                    {selectedCategory === 'All' ? (searchQuery ? `Search: "${searchQuery}"` : 'Best Selling Products') : selectedCategory}
                    </h2>
                    {selectedCategory === 'All' && !searchQuery && (
                        <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">
                            Top quality products selected for you
                        </p>
                    )}
                </div>

                <div className="flex flex-wrap items-center gap-3">
                    {/* Filter Toggle */}
                    <label className="flex items-center gap-2 cursor-pointer bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 px-3 py-2 rounded-lg hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors select-none shadow-sm">
                    <input 
                        type="checkbox" 
                        checked={showInStockOnly} 
                        onChange={() => setShowInStockOnly(!showInStockOnly)}
                        className="w-4 h-4 text-emerald-600 rounded border-gray-300 dark:border-gray-600 focus:ring-emerald-500 dark:focus:ring-emerald-500 dark:bg-gray-700"
                    />
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">In Stock</span>
                    </label>

                    {/* Sort Dropdown */}
                    <div className="relative group">
                    <select
                        value={sortBy}
                        onChange={(e) => setSortBy(e.target.value as SortOption)}
                        className="appearance-none bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-300 text-sm font-medium rounded-lg pl-4 pr-10 py-2 focus:outline-none focus:ring-2 focus:ring-emerald-500 hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors cursor-pointer shadow-sm"
                    >
                        <option value="featured">Sort by: Featured</option>
                        <option value="price-asc">Price: Low to High</option>
                        <option value="price-desc">Price: High to Low</option>
                        <option value="name-asc">Name: A-Z</option>
                    </select>
                    <div className="absolute inset-y-0 right-3 flex items-center pointer-events-none">
                        <ArrowUpDown className="w-4 h-4 text-gray-400 dark:text-gray-500" />
                    </div>
                    </div>
                </div>
             </div>
          </div>
        </div>

        {/* Product Grid */}
        {filteredProducts.length > 0 ? (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4 md:gap-6">
            {filteredProducts.map((product) => (
              <ProductCard
                key={product.id}
                product={product}
                onAddToCart={addToCart}
                onView={handleViewProduct}
              />
            ))}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-20 text-center bg-white dark:bg-gray-900 rounded-3xl border border-dashed border-gray-200 dark:border-gray-800">
            <div className="w-20 h-20 bg-gray-50 dark:bg-gray-800 rounded-full flex items-center justify-center mb-6">
              <SlidersHorizontal className="w-10 h-10 text-gray-400 dark:text-gray-500" />
            </div>
            <h3 className="text-xl font-bold text-gray-800 dark:text-gray-200 mb-2">No items found</h3>
            <p className="text-gray-500 dark:text-gray-400 max-w-xs mx-auto mb-8">
              We couldn't find what you're looking for. Try adjusting your filters.
            </p>
            <button 
              onClick={() => { 
                setSearchQuery(''); 
                setSelectedCategory('All'); 
                setShowInStockOnly(false);
                setSortBy('featured');
              }}
              className="text-emerald-700 dark:text-emerald-400 font-bold hover:underline bg-emerald-50 dark:bg-emerald-900/20 px-8 py-3 rounded-xl transition-colors"
            >
              Clear All Filters
            </button>
          </div>
        )}

        {/* Recently Viewed Section */}
        {recentlyViewedProducts.length > 0 && (
          <div className="mt-20">
            <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-emerald-100 dark:bg-emerald-900/30 rounded-full text-emerald-600 dark:text-emerald-400">
                        <Clock className="w-5 h-5" />
                    </div>
                    <h3 className="text-2xl font-bold text-gray-800 dark:text-gray-100">Recently Viewed</h3>
                </div>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
              {recentlyViewedProducts.map(product => (
                <ProductCard
                  key={`recent-${product.id}`}
                  product={product}
                  onAddToCart={addToCart}
                  onView={handleViewProduct}
