               <div className="w-full flex rounded-full overflow-hidden bg-white dark:bg-gray-800 shadow-lg border-2 border-transparent focus-within:border-yellow-400 transition-colors">
                  <input
                    type="text"
                    placeholder="Search for fresh fruits, vegetables & more..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="flex-1 px-6 py-2.5 outline-none bg-transparent text-gray-900 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 text-sm"
                  />
                  <button className="bg-yellow-400 hover:bg-yellow-500 text-gray-900 w-12 flex items-center justify-center transition-colors">
                    <Search className="w-5 h-5" />
                  </button>
               </div>
            </div>

            {/* Mobile Search Icon */}
            <button className="md:hidden text-white p-2">
               <Search className="w-6 h-6" />
            </button>

            {/* Actions */}
            <div className="flex items-center gap-2 md:gap-5 text-white">
              <button
                onClick={toggleTheme}
                className="p-2 hover:bg-white/10 rounded-full transition-colors"
              >
                 {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
              </button>

              <div className="hidden md:flex items-center gap-3 cursor-pointer hover:bg-white/10 p-1.5 px-3 rounded-lg transition-colors">
                 <User className="w-5 h-5" />
                 <span className="font-medium text-sm">Account</span>
              </div>

              <button
                onClick={() => setIsCartOpen(true)}
                className="relative p-2 flex items-center gap-3 group"
              >
                <div className="relative">
                  <ShoppingCart className="w-6 h-6" />
                  {cartCount > 0 && (
                    <span className="absolute -top-1.5 -right-1.5 bg-yellow-400 text-gray-900 text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full shadow-sm">
                      {cartCount}
                    </span>
                  )}
                </div>
                <span className="hidden md:block font-bold text-sm group-hover:text-yellow-400 transition-colors">Cart</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Secondary Nav / Category Strip (Mobile scrollable) */}
