import React, { useState } from 'react';
import { X, Package, Trash2, Plus, DollarSign, Users, ShoppingBag, BarChart3, Upload, Search, ArrowRight, Image as ImageIcon } from 'lucide-react';
import { Product, Category } from '../types';

interface AdminDashboardProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onRemoveProduct: (id: string) => void;
}

const UNIVERSAL_UNITS = [
  'kg', 'g', 'lb', 'oz', 
  'L', 'ml', 'gallon', 
  'each', 'pack', 'bunch', 'dozen', 
  'tin', 'jar', 'bottle', 'can'
];

export default function AdminDashboard({ isOpen, onClose, products, onAddProduct, onRemoveProduct }: AdminDashboardProps) {
  const [activeTab, setActiveTab] = useState<'overview' | 'products'>('overview');
  const [isAddMode, setIsAddMode] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // New Product Form State
  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '',
    price: 0,
    category: Category.VEGETABLES,
    unit: 'kg',
    image: '',
    images: [],
    description: '',
    inStock: true
  });

  if (!isOpen) return null;

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);

      Promise.all(files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      })).then(base64Images => {
        setNewProduct(prev => ({
            ...prev,
            // If main image is empty, take the first one, otherwise keep existing
            image: prev.image || base64Images[0], 
            // Append new images to existing list
            images: [...(prev.images || []), ...base64Images]
        }));
      });
    }
  };

  const removeImage = (indexToRemove: number) => {
    setNewProduct(prev => {
      const updatedImages = (prev.images || []).filter((_, idx) => idx !== indexToRemove);
      // If we removed the main image (index 0 usually), update it
      const newMainImage = updatedImages.length > 0 ? updatedImages[0] : '';

      // Note: This logic assumes the first image in array is always the main image for simplicity in this context,
      // or we just pick the first one available if the current 'image' matches the removed one.
      // For this simple implementation, we'll just sync `image` to the first of `images` if `images` changes.

      return {
        ...prev,
        images: updatedImages,
        image: updatedImages[0] || ''
      };
    });
  };

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newProduct.name && newProduct.price && newProduct.image) {
      onAddProduct({
        id: Date.now().toString(),
        name: newProduct.name,
        price: Number(newProduct.price),
        category: newProduct.category as Category,
        unit: newProduct.unit || 'each',
        image: newProduct.image,
        images: newProduct.images,
        description: newProduct.description || 'Fresh item added by admin.',
        inStock: true
      });
      setIsAddMode(false);
      setNewProduct({
        name: '',
        price: 0,
        category: Category.VEGETABLES,
        unit: 'kg',
        image: '',
        images: [],
        description: '',
        inStock: true
      });
    }
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 font-sans">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-900 rounded-2xl w-full max-w-5xl h-[85vh] shadow-2xl overflow-hidden flex flex-col md:flex-row animate-in fade-in zoom-in-95 duration-200">

        {/* Sidebar */}
        <div className="w-full md:w-64 bg-gray-50 dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 flex flex-col">
            <div className="p-6 border-b border-gray-200 dark:border-gray-700">
                <h2 className="font-black text-xl text-[#155e37] dark:text-emerald-400 flex items-center gap-2">
                    <BarChart3 className="w-6 h-6" /> Admin
                </h2>
            </div>
            <nav className="flex-1 p-4 space-y-2">
                <button 
                    onClick={() => { setActiveTab('overview'); setIsAddMode(false); }}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                        activeTab === 'overview' 
                        ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' 
                        : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
                    }`}
                >
                    <BarChart3 className="w-5 h-5" /> Overview
                </button>
                <button 
                    onClick={() => { setActiveTab('products'); setIsAddMode(false); }}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                        activeTab === 'products' 
                        ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' 
                        : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
                    }`}
                >
                    <Package className="w-5 h-5" /> Products
                </button>
            </nav>
            <div className="p-4 border-t border-gray-200 dark:border-gray-700">
                 <button onClick={onClose} className="w-full py-2 text-sm font-bold text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white transition-colors">
                     Exit Dashboard
                 </button>
            </div>
