import React, { useState, useEffect } from 'react';
import { X, Save } from 'lucide-react';
import { Product } from '../types';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  product: Product | null;
  onSave: (product: Product) => void;
}

export default function EditProductModal({ isOpen, onClose, product, onSave }: EditProductModalProps) {
  const [editedProduct, setEditedProduct] = useState<Product | null>(null);

  useEffect(() => {
    if (product) {
      setEditedProduct({ ...product });
    }
  }, [product]);

  if (!isOpen || !editedProduct) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editedProduct) {
      onSave(editedProduct);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 font-sans">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-2xl w-full max-w-lg shadow-2xl p-6 animate-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-bold text-gray-900 dark:text-white">Quick Edit Product</h3>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full">
                <X className="w-5 h-5 text-gray-500" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
            <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Name</label>
                <input 
                    className="w-full p-3 rounded-xl border dark:bg-gray-700 dark:border-gray-600"
                    value={editedProduct.name}
                    onChange={e => setEditedProduct({...editedProduct, name: e.target.value})}
                />
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Price</label>
                    <input 
                        type="number"
                        step="0.01"
                        className="w-full p-3 rounded-xl border dark:bg-gray-700 dark:border-gray-600"
                        value={editedProduct.price}
                        onChange={e => setEditedProduct({...editedProduct, price: parseFloat(e.target.value)})}
                    />
                </div>
                <div>
                     <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Stock Status</label>
                     <select 
                        className="w-full p-3 rounded-xl border dark:bg-gray-700 dark:border-gray-600"
                        value={editedProduct.inStock ? 'true' : 'false'}
                        onChange={e => setEditedProduct({...editedProduct, inStock: e.target.value === 'true'})}
                     >
                         <option value="true">In Stock</option>
                         <option value="false">Out of Stock</option>
                     </select>
                </div>
            </div>
            <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Image URL</label>
                <input 
                    className="w-full p-3 rounded-xl border dark:bg-gray-700 dark:border-gray-600"
                    value={editedProduct.image}
                    onChange={e => setEditedProduct({...editedProduct, image: e.target.value})}
                />
            </div>

            <button type="submit" className="w-full bg-emerald-600 text-white font-bold py-3 rounded-xl hover:bg-emerald-700 flex items-center justify-center gap-2">
                <Save className="w-4 h-4" /> Save Changes
            </button>
        </form>
      </div>
    </div>
  );
}

