    sideBanners,
    onUpdateSideBanners
}: AdminDashboardProps) {
  const [activeTab, setActiveTab] = useState<'overview' | 'products' | 'users' | 'hero' | 'categories'>('overview');
  const [isAddMode, setIsAddMode] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Product View State: 'categories' | 'list'
  const [productViewMode, setProductViewMode] = useState<'categories' | 'list'>('categories');
  const [selectedAdminCategory, setSelectedAdminCategory] = useState<string>('');

  // New Product Form State
  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '',
    price: 0,
    category: categories[0],
    unit: 'kg',
    image: '',
    images: [],
    description: '',
    inStock: true
  });

  // New User Form State
  const [newUser, setNewUser] = useState({
      username: '',
      password: '',
      email: ''
  });

  // New Category State
  const [newCategory, setNewCategory] = useState('');

  // Hero Edit State
  const [editingSlides, setEditingSlides] = useState<HeroSlide[]>(heroSlides);
  const [editingSideBanners, setEditingSideBanners] = useState<SideBanner[]>(sideBanners || []);

  if (!isOpen) return null;

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);

      Promise.all(files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      })).then(base64Images => {
        setNewProduct(prev => ({
            ...prev,
            image: prev.image || base64Images[0], 
            images: [...(prev.images || []), ...base64Images]
        }));
      });
    }
  };

  const handleSlideImageUpload = (e: React.ChangeEvent<HTMLInputElement>, index: number) => {
      if(e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const reader = new FileReader();
          reader.onloadend = () => {
              const newSlides = [...editingSlides];
              newSlides[index].image = reader.result as string;
              setEditingSlides(newSlides);
          };
          reader.readAsDataURL(file);
      }
  };

  const handleSideBannerImageUpload = (e: React.ChangeEvent<HTMLInputElement>, index: number) => {
      if(e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const reader = new FileReader();
          reader.onloadend = () => {
              const newBanners = [...editingSideBanners];
              newBanners[index].image = reader.result as string;
              setEditingSideBanners(newBanners);
          };
          reader.readAsDataURL(file);
      }
  };

  const removeImage = (indexToRemove: number) => {
    setNewProduct(prev => {
      const updatedImages = (prev.images || []).filter((_, idx) => idx !== indexToRemove);
      return {
        ...prev,
        images: updatedImages,
        image: updatedImages[0] || ''
      };
    });
  };

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newProduct.name && newProduct.price && newProduct.image) {
      onAddProduct({
        id: Date.now().toString(),
        name: newProduct.name,
        price: Number(newProduct.price),
        category: newProduct.category || categories[0],
        unit: newProduct.unit || 'each',
        image: newProduct.image,
        images: newProduct.images,
        description: newProduct.description || 'Fresh item added by admin.',
        inStock: true
      });
      setIsAddMode(false);
      setNewProduct({
        name: '',
        price: 0,
        category: categories[0],
        unit: 'kg',
        image: '',
        images: [],
        description: '',
        inStock: true
      });
    }
  };

  const handleAddUserSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if(newUser.username && newUser.password && newUser.email) {
          onAddUser({
              id: Date.now().toString(),
              name: newUser.username,
              email: newUser.email,
              role: 'user', // Default to normal user
              password: newUser.password
          });
          setNewUser({ username: '', password: '', email: '' });
      }
  };

  const handleAddCategorySubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if(newCategory && !categories.includes(newCategory)) {
          onAddCategory(newCategory);
          setNewCategory('');
      }
  };

  // Filter products based on selected category and search term
  const filteredProducts = products.filter(p => {
    const matchesCategory = selectedAdminCategory ? p.category === selectedAdminCategory : true;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 font-sans">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-900 rounded-2xl w-full max-w-6xl h-[90vh] shadow-2xl overflow-hidden flex flex-col md:flex-row animate-in fade-in zoom-in-95 duration-200">

        {/* Sidebar */}
        <div className="w-full md:w-64 bg-gray-50 dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 flex flex-col">
            <div className="p-6 border-b border-gray-200 dark:border-gray-700">
                <h2 className="font-black text-xl text-[#155e37] dark:text-emerald-400 flex items-center gap-2">
                    <BarChart3 className="w-6 h-6" /> Admin
                </h2>
            </div>
            <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
                <button 
                    onClick={() => { setActiveTab('overview'); setIsAddMode(false); }}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                        activeTab === 'overview' 
                        ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' 
                        : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
                    }`}
                >
                    <BarChart3 className="w-5 h-5" /> Overview
                </button>
                <button 
                    onClick={() => { setActiveTab('products'); setIsAddMode(false); setProductViewMode('categories'); }}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                        activeTab === 'products' 
                        ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' 
                        : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
                    }`}
                >
                    <Package className="w-5 h-5" /> Products
                </button>
                <button 
                    onClick={() => { setActiveTab('categories'); setIsAddMode(false); }}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                        activeTab === 'categories' 
                        ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' 
                        : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
                    }`}
                >
                    <Layout className="w-5 h-5" /> Categories
                </button>
                <button 
                    onClick={() => { setActiveTab('users'); setIsAddMode(false); }}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                        activeTab === 'users' 
                        ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' 
                        : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
                    }`}
                >
                    <Users className="w-5 h-5" /> Manage Users
                </button>
                <button 
                    onClick={() => { setActiveTab('hero'); setIsAddMode(false); setEditingSlides([...heroSlides]); if(sideBanners) setEditingSideBanners([...sideBanners]); }}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                        activeTab === 'hero' 
                        ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' 
                        : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
                    }`}
                >
                    <ImageIcon className="w-5 h-5" /> Hero & Banners
                </button>
            </nav>
            <div className="p-4 border-t border-gray-200 dark:border-gray-700">
                 <button onClick={onClose} className="w-full py-2 text-sm font-bold text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white transition-colors">
                     Exit Dashboard
                 </button>
            </div>
        </div>

        {/* Main Content */}
        <div className="flex-1 flex flex-col overflow-hidden bg-white dark:bg-gray-900">
            {/* Header */}
            <div className="p-6 border-b border-gray-100 dark:border-gray-800 flex justify-between items-center bg-white dark:bg-gray-900 sticky top-0 z-10">
                <h3 className="text-2xl font-bold text-gray-900 dark:text-white capitalize">
                    {activeTab === 'overview' ? 'Dashboard Overview' : `${activeTab} Management`}
                </h3>
                <div className="flex items-center gap-3">
                    <span className="text-sm text-gray-500 dark:text-gray-400 bg-gray-100 dark:bg-gray-800 px-3 py-1 rounded-full">
                        Admin Mode
                    </span>
                    <button onClick={onClose} className="md:hidden p-2 bg-gray-100 rounded-full">
                        <X className="w-5 h-5" />
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6">
                {activeTab === 'overview' && (
                    <div className="space-y-6">
                        {/* Stats Cards */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div className="bg-blue-50 dark:bg-blue-900/10 p-6 rounded-2xl border border-blue-100 dark:border-blue-800">
                                <div className="flex items-center justify-between mb-4">
                                    <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-xl">
                                        <DollarSign className="w-6 h-6" />
                                    </div>
                                    <span className="text-xs font-bold text-green-600 bg-green-100 px-2 py-1 rounded">+12.5%</span>
                                </div>
                                <p className="text-gray-500 dark:text-gray-400 text-sm font-medium">Total Revenue</p>
                                <h4 className="text-2xl font-black text-gray-900 dark:text-white">$24,500.00</h4>
                            </div>
                            <div className="bg-orange-50 dark:bg-orange-900/10 p-6 rounded-2xl border border-orange-100 dark:border-orange-800">
                                <div className="flex items-center justify-between mb-4">
                                    <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-xl">
                                        <Users className="w-6 h-6" />
                                    </div>
                                    <span className="text-xs font-bold text-green-600 bg-green-100 px-2 py-1 rounded">+5.2%</span>
                                </div>
                                <p className="text-gray-500 dark:text-gray-400 text-sm font-medium">Total Users</p>
                                <h4 className="text-2xl font-black text-gray-900 dark:text-white">{users.length}</h4>
                            </div>
                            <div className="bg-purple-50 dark:bg-purple-900/10 p-6 rounded-2xl border border-purple-100 dark:border-purple-800">
                                <div className="flex items-center justify-between mb-4">
                                    <div className="p-3 bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 rounded-xl">
                                        <Package className="w-6 h-6" />
                                    </div>
                                    <span className="text-xs font-bold text-gray-500 bg-gray-100 px-2 py-1 rounded">Active</span>
                                </div>
                                <p className="text-gray-500 dark:text-gray-400 text-sm font-medium">Total Products</p>
                                <h4 className="text-2xl font-black text-gray-900 dark:text-white">{products.length}</h4>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'users' && (
                    <div className="space-y-8">
                        {/* Add User Section */}
                        <div className="bg-gray-50 dark:bg-gray-800/50 p-6 rounded-2xl border border-gray-200 dark:border-gray-700">
                            <h4 className="font-bold text-lg mb-4 text-gray-900 dark:text-white flex items-center gap-2">
                                <UserPlus className="w-5 h-5 text-emerald-600" /> Add New User
                            </h4>
                            <form onSubmit={handleAddUserSubmit} className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                                <div>
                                    <label className="text-xs font-bold text-gray-500 uppercase">Username</label>
                                    <input 
                                        type="text" 
                                        className="w-full mt-1 p-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" 
                                        value={newUser.username}
                                        onChange={e => setNewUser({...newUser, username: e.target.value})}
                                        required
                                    />
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-gray-500 uppercase">Email</label>
                                    <input 
                                        type="email" 
                                        className="w-full mt-1 p-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" 
                                        value={newUser.email}
                                        onChange={e => setNewUser({...newUser, email: e.target.value})}
                                        required
                                    />
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-gray-500 uppercase">Password</label>
                                    <input 
                                        type="text" 
                                        className="w-full mt-1 p-2 rounded-lg border dark:bg-gray-700 dark:border-gray-600" 
                                        value={newUser.password}
                                        onChange={e => setNewUser({...newUser, password: e.target.value})}
                                        required
                                    />
                                </div>
                                <button type="submit" className="bg-emerald-600 text-white font-bold py-2 rounded-lg hover:bg-emerald-700">Add User</button>
                            </form>
                        </div>

                        {/* Users List */}
                        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-2xl overflow-hidden">
                             <table className="w-full text-left">
                                <thead className="bg-gray-50 dark:bg-gray-700/50 text-gray-500 dark:text-gray-400 text-xs uppercase font-bold">
                                    <tr>
                                        <th className="p-4">Name</th>
                                        <th className="p-4">Email</th>
                                        <th className="p-4">Role</th>
                                        <th className="p-4">Password (Visible)</th>
                                        <th className="p-4 text-right">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                    {users.map(u => (
                                        <tr key={u.id}>
                                            <td className="p-4 font-medium">{u.name}</td>
                                            <td className="p-4 text-gray-500">{u.email}</td>
                                            <td className="p-4">
                                                <span className={`text-xs font-bold px-2 py-1 rounded-full ${u.role === 'admin' ? 'bg-purple-100 text-purple-700' : 'bg-blue-100 text-blue-700'}`}>
                                                    {u.role}
                                                </span>
                                            </td>
                                            <td className="p-4 font-mono text-sm text-gray-500">{u.password || '****'}</td>
                                            <td className="p-4 text-right">
                                                {u.id !== 'admin-1' && (
                                                    <button onClick={() => onRemoveUser(u.id)} className="text-red-500 hover:bg-red-50 p-2 rounded">
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                             </table>
                        </div>
                    </div>
                )}

                {activeTab === 'categories' && (
                    <div className="space-y-8">
                         <div className="bg-gray-50 dark:bg-gray-800/50 p-6 rounded-2xl border border-gray-200 dark:border-gray-700">
                             <h4 className="font-bold text-lg mb-4 text-gray-900 dark:text-white flex items-center gap-2">
                                <Plus className="w-5 h-5 text-emerald-600" /> Add New Category
                             </h4>
                             <form onSubmit={handleAddCategorySubmit} className="flex gap-4">
                                 <input 
                                     type="text" 
                                     className="flex-1 p-3 rounded-xl border dark:bg-gray-700 dark:border-gray-600" 
                                     placeholder="Category Name"
                                     value={newCategory}
                                     onChange={e => setNewCategory(e.target.value)}
                                 />
                                 <button type="submit" className="bg-emerald-600 text-white px-6 font-bold rounded-xl hover:bg-emerald-700">Add</button>
                             </form>
                         </div>
                         <div className="flex flex-wrap gap-3">
                             {categories.map((cat, idx) => (
                                 <div key={idx} className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 px-4 py-3 rounded-xl shadow-sm flex items-center gap-3">
                                     <span className="font-bold text-gray-700 dark:text-gray-200">{cat}</span>
                                     <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
                                 </div>
                             ))}
                         </div>
                    </div>
                )}

                {activeTab === 'hero' && (
                    <div className="space-y-12">
                        {/* Main Slides Section */}
                        <div className="space-y-6">
                            <h4 className="font-bold text-xl text-gray-800 dark:text-gray-200 border-b pb-2">Main Slider Images</h4>
                            {editingSlides.map((slide, idx) => (
                                <div key={idx} className="bg-white dark:bg-gray-800 p-6 rounded-2xl border border-gray-200 dark:border-gray-700 shadow-sm">
                                    <h4 className="font-bold text-gray-500 text-sm uppercase mb-4">Slide {idx + 1}</h4>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                        <div className="space-y-4">
                                            <div>
                                                <label className="text-xs font-bold text-gray-400">Title</label>
                                                <input 
                                                    className="w-full mt-1 p-2 border rounded dark:bg-gray-700 dark:border-gray-600"
                                                    value={slide.title}
                                                    onChange={e => {
                                                        const newSlides = [...editingSlides];
                                                        newSlides[idx].title = e.target.value;
                                                        setEditingSlides(newSlides);
                                                    }}
                                                />
                                            </div>
                                            <div>
                                                <label className="text-xs font-bold text-gray-400">Subtitle</label>
                                                <input 
                                                    className="w-full mt-1 p-2 border rounded dark:bg-gray-700 dark:border-gray-600"
                                                    value={slide.subtitle}
                                                    onChange={e => {
                                                        const newSlides = [...editingSlides];
                                                        newSlides[idx].subtitle = e.target.value;
                                                        setEditingSlides(newSlides);
                                                    }}
                                                />
                                            </div>
                                            <div>
                                                <label className="text-xs font-bold text-gray-400 mb-2 block">Image Source (URL or Upload)</label>
                                                <input 
                                                    className="w-full mb-2 p-2 border rounded dark:bg-gray-700 dark:border-gray-600"
                                                    value={slide.image}
                                                    onChange={e => {
                                                        const newSlides = [...editingSlides];
                                                        newSlides[idx].image = e.target.value;
                                                        setEditingSlides(newSlides);
                                                    }}
                                                    placeholder="Enter Image URL"
                                                />
                                                <div className="relative border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-3 text-center cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors">
                                                    <input 
                                                        type="file" 
                                                        accept="image/*"
                                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                                        onChange={(e) => handleSlideImageUpload(e, idx)}
                                                    />
                                                    <span className="text-xs font-bold text-emerald-600">Upload File</span>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="bg-gray-100 dark:bg-gray-900 rounded-xl overflow-hidden h-48 relative">
                                            <img src={slide.image} className="w-full h-full object-cover" alt="Preview" />
                                            <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                                                <h3 className="text-white font-bold text-center px-4">{slide.title}</h3>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>

                        {/* Side Banners Section */}
                        {onUpdateSideBanners && editingSideBanners.length > 0 && (
                            <div className="space-y-6">
                                <h4 className="font-bold text-xl text-gray-800 dark:text-gray-200 border-b pb-2">Side Banners</h4>
                                {editingSideBanners.map((banner, idx) => (
                                    <div key={idx} className="bg-white dark:bg-gray-800 p-6 rounded-2xl border border-gray-200 dark:border-gray-700 shadow-sm">
