import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Ban, Image, Star, Eye, Pencil } from 'lucide-react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onAddToCart: (product: Product, quantity?: number, e?: React.MouseEvent) => void;
  onView: (product: Product) => void;
  isAdmin?: boolean;
  onEdit?: (product: Product) => void;
}

const ProductCard: React.FC<ProductCardProps> = ({ product, onAddToCart, onView, isAdmin, onEdit }) => {
  const [imageError, setImageError] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isHovered, setIsHovered] = useState(false);

  // Reset error state if product image changes
  useEffect(() => {
    setImageError(false);
  }, [product.image, product.images]);

  // Determine available images
  const images = useMemo(() => {
      // If we have an array of images, use it.
      // If not, use the main image.
      // Filter out empty strings to be safe.
      const imgs = (product.images && product.images.length > 0) 
        ? product.images 
        : (product.image ? [product.image] : []);
      return imgs.filter(Boolean);
  }, [product]);

  // Slideshow effect on hover
  useEffect(() => {
    let interval: number;
    if (isHovered && images.length > 1) {
      interval = window.setInterval(() => {
        setCurrentImageIndex((prev) => (prev + 1) % images.length);
      }, 1500); // Slow smooth switch every 1.5s
    } else {
      setCurrentImageIndex(0); // Reset to main image when not hovered
    }
    return () => clearInterval(interval);
  }, [isHovered, images.length]);

  // Render stars based on rating (default to 4.5 if missing)
  const rating = product.rating || 4.5;
  const fullStars = Math.floor(rating);
  const hasHalfStar = rating % 1 >= 0.5;

  return (
    <div 
      className={`group bg-white dark:bg-gray-800 rounded-2xl border border-gray-50 dark:border-gray-700/50 hover:border-emerald-100 dark:hover:border-emerald-900 shadow-[0_2px_8px_rgba(0,0,0,0.04)] hover:shadow-lg transition-all duration-300 overflow-hidden flex flex-col h-full cursor-pointer relative hover:-translate-y-1`}
      onClick={() => onView(product)}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Badges */}
      {product.inStock && (
        <div className="absolute top-3 left-3 z-10">
          <span className="bg-yellow-400 text-yellow-900 text-[10px] font-bold px-2 py-1 rounded shadow-sm">
             FRESH
          </span>
        </div>
      )}

      {/* Action Overlay */}
      <div className="absolute top-3 right-3 z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col gap-2">
         {isAdmin && onEdit && (
           <button 
             onClick={(e) => {
               e.stopPropagation();
               onEdit(product);
             }}
             className="bg-blue-600 hover:bg-blue-700 text-white p-2 rounded-full shadow-md transition-colors"
             title="Edit Product"
           >
              <Pencil className="w-4 h-4" />
           </button>
         )}
         <button className="bg-white dark:bg-gray-700 p-2 rounded-full shadow-md text-gray-500 hover:text-emerald-600 transition-colors">
            <Eye className="w-4 h-4" />
         </button>
      </div>

      {/* Image Container */}
      <div className="relative w-full aspect-square overflow-hidden bg-gray-50 dark:bg-gray-800">
        {images.length > 0 && !imageError ? (
          <>
            {/* Show all images absolutely positioned to allow cross-fade */}
            {images.map((img, idx) => (
               <img
                key={`${product.id}-img-${idx}`}
                src={img}
                alt={product.name}
                className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-700 ease-in-out ${
                  idx === currentImageIndex ? 'opacity-100' : 'opacity-0'
                } ${product.inStock ? 'group-hover:scale-105 transition-transform duration-[2000ms]' : 'grayscale opacity-50'}`}
                loading="lazy"
                onError={() => {
                    // If the main image fails, trigger error state
                    if (idx === 0) setImageError(true);
                }}
              />
            ))}
          </>
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-800 text-gray-300 dark:text-gray-600">
            <div className="bg-white dark:bg-gray-700 p-4 rounded-full mb-2 shadow-sm">
                <Image className="w-8 h-8 opacity-30 text-emerald-600" />
            </div>
            <span className="text-[10px] uppercase font-bold tracking-wider opacity-50">No Preview</span>
          </div>
        )}

        {!product.inStock && (
          <div className="absolute inset-0 bg-white/60 dark:bg-black/60 flex items-center justify-center backdrop-blur-[1px] z-10">
            <div className="bg-gray-900 text-white text-xs font-bold px-3 py-1.5 rounded-full">
              Out of Stock
            </div>
          </div>
        )}
      </div>

      <div className="p-4 flex flex-col flex-grow">
        <div className="mb-2">
           <span className="text-[10px] uppercase font-bold text-gray-400 dark:text-gray-500 tracking-wide">{product.category}</span>
           <h3 className={`font-bold text-gray-800 dark:text-gray-100 leading-tight mb-1 truncate text-sm md:text-base ${!product.inStock && 'text-gray-400'}`}>
            {product.name}
           </h3>
           <div className="flex items-center gap-1">
              <div className="flex text-yellow-400 text-[10px]">
                 {[...Array(5)].map((_, i) => (
                    <Star 
                        key={i} 
                        className={`w-3 h-3 ${i < fullStars ? 'fill-current' : (i === fullStars && hasHalfStar ? 'fill-current opacity-50' : 'text-gray-200 dark:text-gray-700')}`} 
                    />
                 ))}
              </div>
              <span className="text-[10px] text-gray-400 font-medium">({rating})</span>
           </div>
        </div>

        <div className="mt-auto flex items-center justify-between pt-3 border-t border-gray-50 dark:border-gray-800">
           <div>
              <div className="flex items-baseline gap-1">
                 <span className="text-lg font-bold text-emerald-700 dark:text-emerald-400">
                    ${product.price.toFixed(2)}
                 </span>
                 <span className="text-xs text-gray-400 line-through">
                    ${(product.price * 1.2).toFixed(2)}
                 </span>
              </div>
           </div>

           {product.inStock ? (
             <button 
               onClick={(e) => {
                 e.stopPropagation();
                 onAddToCart(product, 1, e);
               }}
               className="bg-emerald-100 dark:bg-emerald-900/30 hover:bg-emerald-600 dark:hover:bg-emerald-500 text-emerald-700 dark:text-emerald-400 hover:text-white px-4 py-2 rounded-full transition-all font-bold flex items-center gap-2 group/btn shadow-sm hover:shadow-md"
             >
               <span className="text-xs font-bold">Add</span>
               <Plus className="w-4 h-4" />
             </button>
           ) : (
             <button disabled className="bg-gray-100 dark:bg-gray-700 text-gray-400 rounded-full p-2 cursor-not-allowed">
               <Ban className="w-4 h-4" />
             </button>
           )}
        </div>
      </div>
    </div>
  );
};

