                    </p>
                    <button 
                    onClick={() => { 
                        setSearchQuery(''); 
                        setSelectedCategory('All'); 
                        setShowInStockOnly(false);
                        setSortBy('featured');
                    }}
                    className="text-emerald-700 dark:text-emerald-400 font-bold hover:underline bg-emerald-50 dark:bg-emerald-900/20 px-8 py-3 rounded-xl transition-colors"
                    >
                    Clear All Filters
                    </button>
                </div>
                )}
            </>
        )}

        {/* Recently Viewed Section (Only show if we are browsing) */}
        {recentlyViewedProducts.length > 0 && (
          <div className="mt-20 pt-10 border-t border-gray-200 dark:border-gray-800">
            <div className="flex items-center justify-between mb-8">
