                <div className="w-10 h-10 bg-[#155e37] rounded-xl flex items-center justify-center text-white font-bold text-xl">H</div>
                <span className="font-bold text-gray-900 dark:text-white text-2xl">H Mart</span>
              </div>
              <p className="text-gray-500 dark:text-gray-400 leading-relaxed mb-6">
                H Mart makes online grocery shopping fast and easy. Get groceries delivered to your door in minutes.
              </p>
              <div className="flex gap-4">
                 {/* Social placeholders */}
                 <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center text-gray-600 dark:text-gray-400 hover:bg-[#155e37] hover:text-white transition-colors cursor-pointer">FB</div>
                 <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center text-gray-600 dark:text-gray-400 hover:bg-[#155e37] hover:text-white transition-colors cursor-pointer">TW</div>
                 <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center text-gray-600 dark:text-gray-400 hover:bg-[#155e37] hover:text-white transition-colors cursor-pointer">IG</div>
              </div>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 dark:text-gray-100 mb-6 text-lg">Shop Categories</h4>
              <ul className="space-y-3 text-gray-500 dark:text-gray-400">
                {categories.map(cat => (
                    <li key={cat}><button onClick={() => setSelectedCategory(cat)} className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">{cat}</button></li>
                ))}
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 dark:text-gray-100 mb-6 text-lg">Customer Service</h4>
              <ul className="space-y-3 text-gray-500 dark:text-gray-400">
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">About Us</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Contact Us</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Privacy Policy</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">Terms & Conditions</a></li>
                <li><a href="#" className="hover:text-[#155e37] dark:hover:text-emerald-400 transition-colors">FAQ</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 dark:text-gray-100 mb-6 text-lg">Contact Us</h4>
              <ul className="space-y-4 text-gray-500 dark:text-gray-400">
                <li className="flex items-start gap-3">
                    <span className="text-xl">📍</span>
                    <span>1234 Grocery St, Market City, ST 12345</span>
                </li>
                <li className="flex items-center gap-3">
                    <span className="text-xl">📞</span>
                    <span>+1 (555) 123-4567</span>
                </li>
                <li className="flex items-center gap-3">
                    <span className="text-xl">✉️</span>
                    <span>support@h-mart.com</span>
                </li>
              </ul>
            </div>
          </div>
          <div className="border-t border-gray-100 dark:border-gray-800 pt-8 flex flex-col md:flex-row justify-between items-center gap-4">
             <p className="text-gray-400 dark:text-gray-500 text-sm">
                © {new Date().getFullYear()} H Mart. All rights reserved.
            </p>
            <div className="flex gap-4">
               <div className="h-8 w-12 bg-gray-200 dark:bg-gray-700 rounded"></div>
               <div className="h-8 w-12 bg-gray-200 dark:bg-gray-700 rounded"></div>
               <div className="h-8 w-12 bg-gray-200 dark:bg-gray-700 rounded"></div>
            </div>
          </div>
        </div>
      </footer>

      {/* Overlays */}
      <ProductDetailsModal 
        product={selectedProduct}
        isOpen={!!selectedProduct}
        onClose={() => setSelectedProduct(null)}
        onAddToCart={addToCart}
      />

      <EditProductModal 
        isOpen={!!editingProduct}
        product={editingProduct}
        onClose={() => setEditingProduct(null)}
        onSave={handleQuickEdit}
        onDelete={() => {
            if (editingProduct) {
                // Ensure ID is passed correctly and close modal immediately
                handleRemoveProduct(editingProduct.id);
                setEditingProduct(null);
            }
        }}
      />

      <CartSidebar
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        items={cartItems}
        onUpdateQuantity={updateQuantity}
        onRemoveItem={removeItem}
        onAddToCart={addToCart}
      />

      <LocationModal 
        isOpen={isLocationModalOpen}
        onClose={() => setIsLocationModalOpen(false)}
        currentLocation={location}
        onSelectLocation={setLocation}
      />

      <AuthModal 
        isOpen={isAuthModalOpen}
        onClose={() => setIsAuthModalOpen(false)}
        onLogin={handleLogin}
        onSignup={handleSignup}
      />

      {user && (
        <OnboardingModal 
            isOpen={isOnboardingOpen}
            onClose={() => setIsOnboardingOpen(false)}
            user={user}
        />
      )}

      <AdminDashboard 
        isOpen={isAdminDashboardOpen}
        onClose={() => setIsAdminDashboardOpen(false)}
        products={products}
        onAddProduct={handleAddProduct}
        onRemoveProduct={handleRemoveProduct}
        users={users}
        onAddUser={handleAddUser}
        onRemoveUser={handleRemoveUser}
        heroSlides={heroSlides}
        onUpdateHero={handleUpdateHero}
        categories={categories}
        onAddCategory={handleAddCategory}
        sideBanners={sideBanners}
        onUpdateSideBanners={handleUpdateSideBanners}
      />

      {/* Floating AI Assistant Button */}
      <button 
        onClick={handleOpenAssistant}
        className="fixed bottom-6 right-6 z-40 bg-gradient-to-r from-emerald-600 to-teal-500 text-white p-4 rounded-full shadow-lg hover:shadow-2xl hover:scale-110 transition-all duration-300 group flex items-center justify-center"
      >
        <MessageCircle className="w-6 h-6 animate-pulse" />
        <span className="absolute right-full mr-3 bg-white dark:bg-gray-800 text-gray-800 dark:text-white text-xs font-bold px-3 py-1.5 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap shadow-md pointer-events-none">
            Ask H Mart AI
        </span>
      </button>

      <Assistant 
        isOpen={isAssistantOpen} 
        onClose={() => setIsAssistantOpen(false)} 
      />
    </div>
  );
};

