import React, { useState, useEffect } from 'react';
import { X, Mail, Lock, User, ArrowRight, AlertCircle } from 'lucide-react';
import { User as UserType } from '../types';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLogin: (user: UserType) => void;
  onSignup?: (user: UserType) => void;
}

export default function AuthModal({ isOpen, onClose, onLogin, onSignup }: AuthModalProps) {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({
    username: '', // Still used as name in signup
    password: '',
    email: ''
  });
  const [error, setError] = useState('');

  // Initialize Google Sign-In
  useEffect(() => {
    if (isOpen && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          // REPLACE WITH YOUR ACTUAL GOOGLE CLIENT ID
          client_id: "YOUR_GOOGLE_CLIENT_ID", 
          callback: handleGoogleResponse
        });
        (window as any).google.accounts.id.renderButton(
          document.getElementById("googleSignInDiv"),
          { theme: "outline", size: "large", width: "100%" }
        );
      } catch (err) {
        console.error("Google Sign-In Error:", err);
      }
    }
  }, [isOpen]);

  const handleGoogleResponse = (response: any) => {
    try {
        // Decode the JWT token to get user info
        const userObject = parseJwt(response.credential);
        const newUser = {
            id: userObject.sub || Date.now().toString(),
            name: userObject.name || 'Google User',
            email: userObject.email || 'google@example.com',
            role: 'user' as const
        };

        if (onSignup) {
            onSignup(newUser);
        } else {
            onLogin(newUser);
        }
        onClose();
    } catch (error) {
        console.error("Error parsing Google token", error);
        setError("Failed to sign in with Google.");
    }
  };

  const parseJwt = (token: string) => {
    try {
        var base64Url = token.split('.')[1];
        var base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        var jsonPayload = decodeURIComponent(window.atob(base64).split('').map(function(c) {
            return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        return JSON.parse(jsonPayload);
    } catch (e) {
        return {};
    }
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (isLogin) {
      // Updated credentials check
      if (formData.email === 'admin@gmail.com' && formData.password === '12345') {
        onLogin({
          id: 'admin-1',
          name: 'Admin User',
          role: 'admin',
          email: 'admin@gmail.com'
        });
        onClose();
      } else if (formData.email === 'user@gmail.com' && formData.password === 'user') {
        onLogin({
          id: 'user-1',
          name: 'John Doe',
          role: 'user',
          email: 'user@gmail.com'
        });
        onClose();
      } else {
        setError('Invalid credentials.');
      }
    } else {
      // Mock Signup
      if (formData.username && formData.password && formData.email) {
        const newUser = {
          id: Date.now().toString(),
          name: formData.username,
          role: 'user' as const,
          email: formData.email,
          password: formData.password 
        };

        if (onSignup) {
            onSignup(newUser);
        } else {
            onLogin(newUser);
        }
        onClose();
      } else {
        setError('Please fill in all fields');
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 font-sans">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
        <button onClick={onClose} className="absolute top-4 right-4 p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition-colors z-10">
          <X className="w-5 h-5 text-gray-500" />
        </button>

        <div className="p-8">
          <div className="text-center mb-8">
            <h2 className="text-3xl font-black text-[#155e37] dark:text-emerald-400 mb-2">H Mart</h2>
            <p className="text-gray-500 dark:text-gray-400">
              {isLogin ? 'Welcome back! Please login to continue.' : 'Create an account to start shopping.'}
            </p>
          </div>

          {error && (
            <div className="mb-6 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl flex items-center gap-2 text-red-600 dark:text-red-400 text-sm font-medium">
              <AlertCircle className="w-4 h-4" />
              {error}
            </div>
          )}

          <div className="space-y-4">
             <div id="googleSignInDiv" className="w-full flex justify-center h-12"></div>

             <div className="flex items-center gap-3">
                 <div className="h-px bg-gray-200 dark:bg-gray-700 flex-1"></div>
                 <span className="text-xs text-gray-400 font-bold uppercase">Or continue with email</span>
                 <div className="h-px bg-gray-200 dark:bg-gray-700 flex-1"></div>
             </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4 mt-4">
            {/* Always show email field for both login and signup */}
            <div className="relative group">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 group-focus-within:text-emerald-600 transition-colors" />
                <input
                  type="email"
                  placeholder="Email Address"
                  className="w-full pl-12 pr-4 py-3 bg-gray-50 dark:bg-gray-700/50 border border-gray-200 dark:border-gray-600 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 transition-all dark:text-white"
                  value={formData.email}
                  onChange={e => setFormData({ ...formData, email: e.target.value })}
                />
            </div>

            {!isLogin && (
                <div className="relative group">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 group-focus-within:text-emerald-600 transition-colors" />
                <input
                    type="text"
                    placeholder="Full Name"
                    className="w-full pl-12 pr-4 py-3 bg-gray-50 dark:bg-gray-700/50 border border-gray-200 dark:border-gray-600 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 transition-all dark:text-white"
                    value={formData.username}
                    onChange={e => setFormData({ ...formData, username: e.target.value })}
                />
                </div>
            )}

            <div className="relative group">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 group-focus-within:text-emerald-600 transition-colors" />
              <input
                type="password"
                placeholder="Password"
                className="w-full pl-12 pr-4 py-3 bg-gray-50 dark:bg-gray-700/50 border border-gray-200 dark:border-gray-600 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 transition-all dark:text-white"
                value={formData.password}
                onChange={e => setFormData({ ...formData, password: e.target.value })}
              />
            </div>

            <button
              type="submit"
              className="w-full py-4 bg-[#155e37] text-white rounded-xl font-bold hover:bg-emerald-800 transition-all shadow-lg shadow-emerald-900/20 flex items-center justify-center gap-2 group"
            >
              {isLogin ? 'Login' : 'Create Account'}
              <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
            </button>
          </form>

          <div className="mt-6 text-center">
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {isLogin ? "Don't have an account?" : "Already have an account?"}{' '}
              <button
                onClick={() => { setIsLogin(!isLogin); setError(''); }}
                className="text-emerald-600 dark:text-emerald-400 font-bold hover:underline"
              >
                {isLogin ? 'Sign up' : 'Login'}
              </button>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { X, User, Phone, Mail, MapPin, ShoppingBag, Save, Edit2, Camera } from 'lucide-react';
import { User as UserType } from '../types';

interface UserProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: UserType;
  onUpdateUser: (updatedUser: UserType) => void;
}

export default function UserProfileModal({ isOpen, onClose, user, onUpdateUser }: UserProfileModalProps) {
  const [activeTab, setActiveTab] = useState<'details' | 'addresses' | 'orders'>('details');
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: user.name,
    email: user.email,
    phone: user.phone || '',
  });

  if (!isOpen) return null;

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateUser({
      ...user,
      name: formData.name,
      email: formData.email,
      phone: formData.phone
    });
    setIsEditing(false);
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const reader = new FileReader();
          reader.onloadend = () => {
              onUpdateUser({
                  ...user,
                  profileImage: reader.result as string
              });
          };
          reader.readAsDataURL(file);
      }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 font-sans">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-2xl w-full max-w-2xl shadow-2xl overflow-hidden flex flex-col md:flex-row h-[600px] animate-in zoom-in-95 duration-200">

        {/* Sidebar */}
        <div className="w-full md:w-64 bg-gray-50 dark:bg-gray-900 border-r border-gray-100 dark:border-gray-700 p-6 flex flex-col">
            <div className="text-center mb-6 relative group">
                <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-900/30 rounded-full mx-auto flex items-center justify-center text-emerald-600 dark:text-emerald-400 mb-3 overflow-hidden relative border-2 border-emerald-100 dark:border-emerald-800">
                    {user.profileImage ? (
                        <img src={user.profileImage} alt="Profile" className="w-full h-full object-cover" />
                    ) : (
                        <User className="w-10 h-10" />
                    )}
                    <label className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                        <Camera className="w-6 h-6 text-white" />
                        <input type="file" accept="image/*" className="hidden" onChange={handlePhotoUpload} />
                    </label>
                </div>
                <h3 className="font-bold text-gray-900 dark:text-white truncate">{user.name}</h3>
                <p className="text-xs text-gray-500 dark:text-gray-400">{user.email}</p>
            </div>

            <nav className="space-y-2">
                <button 
                    onClick={() => setActiveTab('details')}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'details' ? 'bg-white dark:bg-gray-800 shadow-sm text-emerald-600' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}
                >
                    <User className="w-4 h-4" /> Personal Details
                </button>
                <button 
                    onClick={() => setActiveTab('addresses')}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'addresses' ? 'bg-white dark:bg-gray-800 shadow-sm text-emerald-600' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}
                >
                    <MapPin className="w-4 h-4" /> Saved Addresses
                </button>
                <button 
                    onClick={() => setActiveTab('orders')}
                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'orders' ? 'bg-white dark:bg-gray-800 shadow-sm text-emerald-600' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}
                >
                    <ShoppingBag className="w-4 h-4" /> Order History
                </button>
            </nav>
        </div>

        {/* Content */}
        <div className="flex-1 flex flex-col bg-white dark:bg-gray-800 relative">
            <button onClick={onClose} className="absolute top-4 right-4 p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition-colors z-10">
                <X className="w-5 h-5 text-gray-500" />
            </button>

            <div className="p-8 overflow-y-auto h-full">
                {activeTab === 'details' && (
                    <div className="h-full flex flex-col">
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-xl font-bold text-gray-900 dark:text-white">Personal Details</h2>
                            {!isEditing && (
                                <button onClick={() => setIsEditing(true)} className="text-emerald-600 text-sm font-bold flex items-center gap-1 hover:underline">
                                    <Edit2 className="w-4 h-4" /> Edit
                                </button>
                            )}
                        </div>

                        {isEditing ? (
                            <form onSubmit={handleSave} className="flex flex-col h-full">
                                <div className="space-y-4 flex-1">
                                    <div>
                                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Full Name</label>
                                        <input 
                                            type="text" 
                                            className="w-full p-3 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white"
                                            value={formData.name}
                                            onChange={e => setFormData({...formData, name: e.target.value})}
                                        />
                                    </div>
                                    <div>
                                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Email</label>
                                        <input 
                                            type="email" 
                                            className="w-full p-3 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white"
                                            value={formData.email}
                                            onChange={e => setFormData({...formData, email: e.target.value})}
                                        />
                                    </div>
                                    <div>
                                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Phone Number</label>
                                        <input 
                                            type="tel" 
                                            className="w-full p-3 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white"
                                            value={formData.phone}
                                            onChange={e => setFormData({...formData, phone: e.target.value})}
                                            placeholder="+1 (555) 000-0000"
                                        />
                                    </div>
                                </div>
                                <div className="flex gap-4 pt-6 mt-auto">
                                    <button type="button" onClick={() => setIsEditing(false)} className="flex-1 py-3 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-bold hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors">Cancel</button>
                                    <button type="submit" className="flex-1 bg-emerald-600 text-white py-3 rounded-xl font-bold hover:bg-emerald-700 transition-colors">Save Changes</button>
                                </div>
                            </form>
                        ) : (
                            <div className="space-y-6">
                                <div className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-gray-700/50 rounded-xl">
                                    <div className="p-3 bg-white dark:bg-gray-600 rounded-full shadow-sm">
                                        <User className="w-5 h-5 text-gray-500 dark:text-gray-300" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-400 font-bold uppercase">Full Name</p>
                                        <p className="font-medium text-gray-900 dark:text-white">{user.name}</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-gray-700/50 rounded-xl">
                                    <div className="p-3 bg-white dark:bg-gray-600 rounded-full shadow-sm">
                                        <Mail className="w-5 h-5 text-gray-500 dark:text-gray-300" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-400 font-bold uppercase">Email Address</p>
                                        <p className="font-medium text-gray-900 dark:text-white">{user.email}</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-gray-700/50 rounded-xl">
                                    <div className="p-3 bg-white dark:bg-gray-600 rounded-full shadow-sm">
                                        <Phone className="w-5 h-5 text-gray-500 dark:text-gray-300" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-400 font-bold uppercase">Phone Number</p>
                                        <p className="font-medium text-gray-900 dark:text-white">{user.phone || 'Not set'}</p>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {activeTab === 'addresses' && (
                    <div>
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-6">Saved Addresses</h2>
                        {user.savedAddresses && user.savedAddresses.length > 0 ? (
                            <div className="space-y-4">
                                {user.savedAddresses.map((addr, idx) => (
                                    <div key={idx} className="p-4 border border-gray-200 dark:border-gray-700 rounded-xl flex items-start gap-4">
                                        <MapPin className="w-5 h-5 text-emerald-600 mt-1" />
