                )}

                {activeTab === 'orders' && (
                    <div>
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-6">Purchase History</h2>
                        {/* Mock Orders for Demo */}
                        <div className="space-y-4">
