import React, { useState, useEffect } from 'react';
import { X, Save, Trash2, Upload, Plus, Image } from 'lucide-react';
import { Product } from '../types';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  product: Product | null;
  onSave: (product: Product) => void;
  onDelete?: () => void;
}

export default function EditProductModal({ isOpen, onClose, product, onSave, onDelete }: EditProductModalProps) {
  const [editedProduct, setEditedProduct] = useState<Product | null>(null);
  const [urlInput, setUrlInput] = useState('');
  const [highlightsInput, setHighlightsInput] = useState('');

  useEffect(() => {
    if (product) {
        // Ensure images array is initialized if missing, so the gallery works
        const initialImages = (product.images && product.images.length > 0) 
            ? product.images 
            : (product.image ? [product.image] : []);

        setEditedProduct({ 
            ...product,
            images: initialImages
        });
        setHighlightsInput(product.highlights ? product.highlights.join(', ') : '');
        setUrlInput('');
    }
  }, [product]);

  if (!isOpen || !editedProduct) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editedProduct) {
      const updatedProduct = {
          ...editedProduct,
          highlights: highlightsInput.split(',').map(s => s.trim()).filter(Boolean)
      };
      onSave(updatedProduct);
      onClose();
    }
  };

  const handleDelete = () => {
      if(onDelete && confirm('Are you sure you want to delete this product?')) {
          onDelete();
      }
  };

  const addImageUrl = () => {
      if (!urlInput.trim()) return;

      setEditedProduct(prev => {
          if (!prev) return null;
          const newImages = [...(prev.images || []), urlInput.trim()];
          return {
              ...prev,
              images: newImages,
              image: newImages[0] // Main image is always first
          };
      });
      setUrlInput('');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
        const file = e.target.files[0];
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = reader.result as string;
            setEditedProduct(prev => {
                if (!prev) return null;
                const newImages = [...(prev.images || []), base64String];
                return {
                    ...prev,
                    image: newImages[0], // Main image is always first
                    images: newImages
                };
            });
        };
        reader.readAsDataURL(file);
    }
  };

  const removeImage = (indexToRemove: number) => {
      setEditedProduct(prev => {
          if (!prev) return null;
          const currentImages = prev.images || [];
          const updatedImages = currentImages.filter((_, idx) => idx !== indexToRemove);

          return {
              ...prev,
              images: updatedImages,
              image: updatedImages.length > 0 ? updatedImages[0] : ''
          };
      });
  };

  return (
    <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 font-sans">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-2xl w-full max-w-lg shadow-2xl p-6 animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
        <div className="flex justify-between items-center mb-6 border-b border-gray-100 dark:border-gray-700 pb-4">
            <h3 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                <span className="bg-emerald-100 dark:bg-emerald-900/30 p-2 rounded-lg text-emerald-600">
                    <Save className="w-5 h-5" />
                </span>
                Quick Edit Product
            </h3>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full">
                <X className="w-5 h-5 text-gray-500" />
            </button>
        </div>

        <div className="overflow-y-auto flex-1 pr-2">
            <form id="edit-form" onSubmit={handleSubmit} className="space-y-6">
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Name</label>
                    <input 
                        className="w-full p-3 rounded-xl border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 outline-none focus:ring-2 focus:ring-emerald-500 text-gray-900 dark:text-white"
                        value={editedProduct.name}
                        onChange={e => setEditedProduct({...editedProduct, name: e.target.value})}
                    />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Price</label>
                        <input 
                            type="number"
                            step="0.01"
                            className="w-full p-3 rounded-xl border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 outline-none focus:ring-2 focus:ring-emerald-500 text-gray-900 dark:text-white"
                            value={editedProduct.price}
                            onChange={e => setEditedProduct({...editedProduct, price: parseFloat(e.target.value)})}
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Stock Status</label>
                        <select 
                            className="w-full p-3 rounded-xl border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 outline-none focus:ring-2 focus:ring-emerald-500 text-gray-900 dark:text-white"
                            value={editedProduct.inStock ? 'true' : 'false'}
                            onChange={e => setEditedProduct({...editedProduct, inStock: e.target.value === 'true'})}
                        >
                            <option value="true">In Stock</option>
                            <option value="false">Out of Stock</option>
                        </select>
                    </div>
                </div>

                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Highlights</label>
                    <input 
                        className="w-full p-3 rounded-xl border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 outline-none focus:ring-2 focus:ring-emerald-500 text-gray-900 dark:text-white"
                        value={highlightsInput}
                        onChange={e => setHighlightsInput(e.target.value)}
                        placeholder="Comma separated values"
                    />
                </div>

                {/* Image Management Section */}
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Product Images Gallery</label>
                    <p className="text-xs text-gray-400 mb-3">Upload multiple images. The first image will be used as the main product cover.</p>

                    {/* Add Image URL Input */}
                    <div className="flex gap-2 mb-4">
                        <input 
                            className="flex-1 p-3 rounded-xl border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 outline-none focus:ring-2 focus:ring-emerald-500 text-sm text-gray-900 dark:text-white"
                            value={urlInput}
                            onChange={e => setUrlInput(e.target.value)}
                            placeholder="Add Image URL..."
                        />
                        <button 
                            type="button"
                            onClick={addImageUrl}
                            className="bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 text-gray-800 dark:text-white px-4 rounded-xl font-bold text-sm transition-colors"
                        >
                            <Plus className="w-5 h-5" />
                        </button>
                    </div>

                    {/* Image Grid & Upload */}
                    <div className="grid grid-cols-4 gap-3">
                        {/* Upload Button */}
                        <div className="relative aspect-square bg-gray-50 dark:bg-gray-700/50 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-xl hover:border-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/10 transition-colors flex flex-col items-center justify-center cursor-pointer group">
                            <input 
                                type="file" 
                                accept="image/*"
                                onChange={handleImageUpload}
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                            />
                            <Upload className="w-6 h-6 text-gray-400 group-hover:text-emerald-500 mb-1" />
                            <span className="text-[10px] text-gray-500 font-bold uppercase">Upload</span>
                        </div>

                        {/* Existing Images */}
                        {editedProduct.images && editedProduct.images.length > 0 ? (
                            editedProduct.images.map((img, idx) => (
                                <div key={idx} className="relative aspect-square rounded-xl overflow-hidden border border-gray-200 dark:border-gray-700 group bg-white dark:bg-gray-900">
                                    <img src={img} alt="" className="w-full h-full object-cover" />
                                    <button 
                                        type="button"
                                        onClick={() => removeImage(idx)}
                                        className="absolute top-1 right-1 p-1 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity transform hover:scale-110"
                                    >
                                        <X className="w-3 h-3" />
                                    </button>
                                    {idx === 0 && (
                                        <div className="absolute bottom-0 inset-x-0 bg-emerald-500 text-white text-[9px] text-center font-bold py-0.5">
                                            MAIN
                                        </div>
                                    )}
                                </div>
                            ))
                        ) : (
                            <div className="col-span-3 flex items-center justify-center border border-dashed border-gray-200 dark:border-gray-700 rounded-xl bg-gray-50 dark:bg-gray-800/50 text-gray-400 text-xs flex-col gap-2 p-4 text-center">
                                <Image className="w-6 h-6 opacity-50" />
                                <span>No Images Available</span>
                            </div>
                        )}
                    </div>
                </div>
            </form>
        </div>

        <div className="pt-6 mt-6 border-t border-gray-100 dark:border-gray-700 flex gap-4">
             {onDelete && (
                 <button 
                    type="button"
                    onClick={handleDelete}
                    className="p-3 bg-red-50 dark:bg-red-900/20 text-red-600 hover:bg-red-100 dark:hover:bg-red-900/40 rounded-xl transition-colors"
                    title="Delete Product"
                 >
                     <Trash2 className="w-5 h-5" />
                 </button>
             )}
            <button 
                type="submit" 
                form="edit-form"
                className="flex-1 bg-emerald-600 text-white font-bold py-3 rounded-xl hover:bg-emerald-700 flex items-center justify-center gap-2 shadow-lg shadow-emerald-900/20"
            >
                <Save className="w-4 h-4" /> Save Changes
            </button>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { X, Clock, Bookmark, ChevronDown, Check, Tag, Gift, CreditCard, SlidersHorizontal, ChevronUp, Image, Star, MessageSquare } from 'lucide-react';
import { Product, Review } from '../types';

interface ProductDetailsModalProps {
  product: Product | null;
  isOpen: boolean;
  onClose: () => void;
  onAddToCart: (product: Product, quantity?: number, e?: React.MouseEvent) => void;
}

const ProductDetailsModal: React.FC<ProductDetailsModalProps> = ({ 
  product, 
  isOpen, 
  onClose,
  onAddToCart 
}) => {
  const [selectedPack, setSelectedPack] = useState(0);
  const [activeImageIndex, setActiveImageIndex] = useState(0);
  const [isOffersOpen, setIsOffersOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'packs' | 'custom'>('packs');
  const [customQuantity, setCustomQuantity] = useState(1);

  // Prevent body scroll when modal is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
      // Reset state on open
      setSelectedPack(0);
      setActiveImageIndex(0);
      setIsOffersOpen(false);
      setActiveTab('packs');
      setCustomQuantity(1);
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  if (!isOpen || !product) return null;

  // Mock data derivation
  const baseMrpMultiplier = 1.3;
  const baseDiscount = 23;

  // Format unit to universal standards if 'each' is used in pack sizes
  const displayUnit = product.unit === 'each' ? 'pack' : product.unit;

  const packOptions = [
    { 
      id: 0, 
      size: `1 ${displayUnit}`, 
      quantity: 1,
      price: product.price, 
      mrp: product.price * baseMrpMultiplier, 
      discount: baseDiscount 
    },
    { 
      id: 1, 
      size: `2 ${displayUnit}s`, 
      quantity: 2,
      price: product.price * 2, 
      mrp: (product.price * 2) * baseMrpMultiplier, 
      discount: baseDiscount 
    }
  ];

  // Custom size calculation
  const customPrice = product.price * customQuantity;
  const customMrp = customPrice * baseMrpMultiplier;

  // Determine current display values based on active tab
  const currentPrice = activeTab === 'packs' ? packOptions[selectedPack].price : customPrice;
  const currentMrp = activeTab === 'packs' ? packOptions[selectedPack].mrp : customMrp;
  const currentQuantity = activeTab === 'packs' ? packOptions[selectedPack].quantity : customQuantity;

  // Determine images to show
  const images = (product.images && product.images.length > 0) 
    ? product.images 
    : (product.image ? [product.image] : []);

  const activeSrc = images[activeImageIndex];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 font-sans">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity"
        onClick={onClose}
      />

      {/* Modal Content */}
      <div className="relative bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-y-auto flex flex-col md:flex-row animate-in fade-in zoom-in-95 duration-200 border border-gray-200 dark:border-gray-700">

        {/* Close Button */}
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 z-20 p-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 rounded-full transition-colors"
        >
          <X className="w-5 h-5 text-gray-500 dark:text-gray-400" />
        </button>

        {/* Left Column: Image Gallery & Reviews */}
        <div className="w-full md:w-1/2 p-6 md:p-8 flex flex-col bg-white dark:bg-gray-800 border-b md:border-b-0 md:border-r border-gray-100 dark:border-gray-700 overflow-y-auto max-h-[90vh] no-scrollbar">

            {/* Main Image Container (Rounded Rectangle) */}
            <div className="relative w-full aspect-[4/3] rounded-2xl overflow-hidden border border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800 flex items-center justify-center mb-4 shadow-sm">
                {activeSrc ? (
                    <img 
                        src={activeSrc} 
                        alt={product.name} 
                        className={`w-full h-full object-cover transition-transform duration-500 ${!product.inStock ? 'grayscale opacity-50' : 'hover:scale-105'}`}
                    />
                ) : (
                    <div className="flex flex-col items-center text-gray-300 dark:text-gray-600">
                        <Image className="w-12 h-12 mb-2 opacity-30" />
                        <span className="text-xs font-bold uppercase tracking-wider">No Preview</span>
                    </div>
                )}
                {!product.inStock && activeSrc && (
                    <div className="absolute inset-0 flex items-center justify-center bg-white/50 dark:bg-black/50 backdrop-blur-sm">
                        <span className="bg-gray-900 text-white px-4 py-2 rounded-full font-bold text-sm shadow-lg">
                            Out of Stock
                        </span>
                    </div>
                )}
            </div>

            {/* Thumbnail Navigation Pane */}
            {images.length > 1 && (
                <div className="flex gap-2 overflow-x-auto pb-2 w-full justify-start no-scrollbar mb-8">
                  {images.map((src, idx) => (
                    <button
                      key={idx}
                      onClick={() => setActiveImageIndex(idx)}
                      className={`relative w-16 h-16 rounded-xl overflow-hidden flex-shrink-0 bg-white dark:bg-gray-700 transition-all ${
                        activeImageIndex === idx 
                          ? 'ring-2 ring-emerald-500 ring-offset-1 dark:ring-offset-gray-800' 
                          : 'opacity-70 hover:opacity-100'
                      }`}
                    >
                      <img 
                        src={src} 
                        alt={`View ${idx + 1}`} 
                        className="w-full h-full object-cover"
                      />
                    </button>
                  ))}
                </div>
            )}

            {/* Reviews Section */}
            <div className="mt-4 border-t border-gray-100 dark:border-gray-700 pt-6">
                <div className="flex items-center gap-2 mb-4">
                    <MessageSquare className="w-5 h-5 text-emerald-600" />
                    <h3 className="font-bold text-gray-900 dark:text-white">Customer Reviews</h3>
                </div>

                {product.reviews && product.reviews.length > 0 ? (
                    <div className="space-y-4">
                        {product.reviews.map((review: Review) => (
                            <div key={review.id} className="bg-gray-50 dark:bg-gray-700/30 p-4 rounded-xl">
                                <div className="flex justify-between items-start mb-2">
                                    <div className="flex flex-col">
                                        <span className="font-bold text-sm text-gray-900 dark:text-white">{review.user}</span>
                                        <span className="text-[10px] text-gray-400">{review.date}</span>
                                    </div>
                                    <div className="flex text-yellow-400">
                                        {[...Array(5)].map((_, i) => (
                                            <Star key={i} className={`w-3 h-3 ${i < review.rating ? 'fill-current' : 'text-gray-300 dark:text-gray-600'}`} />
                                        ))}
                                    </div>
                                </div>
                                <p className="text-xs text-gray-600 dark:text-gray-300 leading-relaxed">
                                    "{review.comment}"
                                </p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <p className="text-sm text-gray-500 italic">No reviews yet for this product.</p>
                )}
            </div>
        </div>

        {/* Right Column: Details */}
        <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col bg-white dark:bg-gray-800">
            {/* Header / Brand */}
            <div className="flex justify-between items-start mb-2">
                <span className="text-gray-500 dark:text-gray-400 text-sm underline decoration-gray-300 dark:decoration-gray-600 cursor-pointer hover:text-gray-800 dark:hover:text-gray-200 transition-colors">
                    {product.category}
                </span>
                <div className="flex items-center gap-1 bg-[#fcf8e3] dark:bg-yellow-900/30 border border-[#faebcc] dark:border-yellow-900/50 text-[#8a6d3b] dark:text-yellow-500 px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wide shadow-sm">
                    <Clock className="w-3 h-3" /> 10 MINS
                </div>
            </div>

            <h1 className="text-xl md:text-2xl font-bold text-gray-900 dark:text-white mb-4 leading-tight tracking-tight">
                {product.name}
            </h1>

            {/* Price Block */}
            <div className="mb-6 border-b border-gray-100 dark:border-gray-700 pb-6">
                <div className="text-sm text-gray-500 dark:text-gray-400 mb-1">
                    MRP: <span className="line-through decoration-gray-400">${currentMrp.toFixed(2)}</span>
                </div>
                <div className="flex items-baseline gap-2 mb-1">
                    <span className="text-2xl font-bold text-gray-900 dark:text-white">
                        Price: ${currentPrice.toFixed(2)}
                    </span>
                </div>
                <div className="flex items-center gap-2 text-sm mb-1">
                    <span className="text-emerald-600 dark:text-emerald-400 font-bold bg-emerald-50 dark:bg-emerald-900/20 px-2 py-0.5 rounded">
                        You Save: {baseDiscount}% OFF
                    </span>
                </div>
                <div className="text-xs text-gray-400 mt-2">
                    (inclusive of all taxes)
                </div>
            </div>

            {/* Promo Banner / Accordion */}
            <div className="mb-6">
               <button 
                 onClick={() => setIsOffersOpen(!isOffersOpen)}
                 className="w-full bg-[#eefbe7] dark:bg-emerald-900/20 border border-[#dff0d8] dark:border-emerald-800 text-[#3c763d] dark:text-emerald-400 px-4 py-3 rounded-md flex justify-between items-center cursor-pointer hover:bg-[#e4f7db] transition-colors shadow-sm group"
               >
                  <span className="font-bold text-sm flex items-center gap-2">
                    <Tag className="w-4 h-4" />
                    Har Din Sasta!
                  </span>
                  {isOffersOpen ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
               </button>

               {/* Expandable Offers List */}
               {isOffersOpen && (
                 <div className="mt-2 bg-gray-50 dark:bg-gray-700/30 rounded-lg p-3 border border-gray-100 dark:border-gray-700 space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="flex gap-3 items-start">
                       <CreditCard className="w-4 h-4 text-emerald-600 mt-1 flex-shrink-0" />
                       <div>
                          <p className="text-xs font-bold text-gray-800 dark:text-gray-200">Bank Offer</p>
                          <p className="text-xs text-gray-600 dark:text-gray-400">10% Instant Discount on HDFC Bank Credit Cards</p>
                       </div>
                    </div>
                    <div className="h-px bg-gray-200 dark:bg-gray-700"></div>
                    <div className="flex gap-3 items-start">
                       <Gift className="w-4 h-4 text-emerald-600 mt-1 flex-shrink-0" />
                       <div>
                          <p className="text-xs font-bold text-gray-800 dark:text-gray-200">Special Price</p>
                          <p className="text-xs text-gray-600 dark:text-gray-400">Get extra 5% off (price inclusive of cashback)</p>
                       </div>
                    </div>
                 </div>
               )}
            </div>

            {/* Actions (Save for later removed) */}
            <div className="flex gap-4 mb-8">
                <button
                    onClick={(e) => onAddToCart(product, currentQuantity, e)}
                    disabled={!product.inStock}
                    className="w-full bg-[#da251d] hover:bg-[#b01e17] text-white font-bold py-4 px-4 rounded-xl shadow-md hover:shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed uppercase text-sm tracking-wider transform active:scale-[0.98]"
                >
                    Add to basket
                </button>
            </div>

            {/* Selection Tabs */}
            <div className="flex border-b border-gray-200 dark:border-gray-700 mb-4">
               <button 
                 onClick={() => setActiveTab('packs')}
                 className={`pb-2 px-4 text-sm font-bold border-b-2 transition-colors ${activeTab === 'packs' ? 'border-emerald-500 text-emerald-600 dark:text-emerald-400' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
               >
                 Pack Sizes
               </button>
               <button 
                 onClick={() => setActiveTab('custom')}
                 className={`pb-2 px-4 text-sm font-bold border-b-2 transition-colors flex items-center gap-2 ${activeTab === 'custom' ? 'border-emerald-500 text-emerald-600 dark:text-emerald-400' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
               >
                 <SlidersHorizontal className="w-3 h-3" /> Custom Size
               </button>
            </div>

            {/* Pack Size / Custom Selection */}
            <div className="mb-8 min-h-[160px]">
              {activeTab === 'packs' ? (
                <div className="space-y-3">
                    {packOptions.map((option, idx) => (
                        <div 
                            key={idx}
                            onClick={() => setSelectedPack(idx)}
                            className={`relative border rounded-lg p-3 cursor-pointer flex justify-between items-center transition-all ${
                                selectedPack === idx 
                                ? 'border-emerald-500 bg-[#f4fcf6] dark:bg-emerald-900/10 ring-1 ring-emerald-500 shadow-sm' 
                                : 'border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600'
                            }`}
                        >
                            <div className="flex flex-col">
                                <div className="flex items-center gap-2">
                                    <span className="font-bold text-sm text-gray-800 dark:text-gray-200">{option.size}</span>
                                </div>
                                <div className="flex items-center gap-2 mt-1">
                                    <span className="font-bold text-sm text-gray-900 dark:text-white">${option.price.toFixed(2)}</span>
                                    <span className="text-xs text-gray-400 line-through">${option.mrp.toFixed(2)}</span>
                                    <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-1.5 py-0.5 rounded">{option.discount}% OFF</span>
                                </div>
                            </div>

                            {selectedPack === idx && (
                                <div className="absolute top-0 right-0 p-1 bg-emerald-500 rounded-bl-lg rounded-tr-lg">
                                    <Check className="w-3 h-3 text-white" />
                                </div>
                            )}

                            {selectedPack === idx && (
                                <div className="flex items-center gap-1 text-gray-400 text-[10px] font-bold uppercase tracking-wide">
                                    <Clock className="w-3 h-3" /> 10 MINS
                                </div>
                            )}
                        </div>
                    ))}
                </div>
              ) : (
                <div className="bg-gray-50 dark:bg-gray-800/50 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
                   <div className="flex justify-between items-center mb-4">
                      <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Choose quantity:</span>
                      <span className="text-lg font-bold text-emerald-600 dark:text-emerald-400 bg-white dark:bg-gray-700 px-3 py-1 rounded shadow-sm border border-emerald-100 dark:border-emerald-900">
                        {customQuantity} {displayUnit}{customQuantity > 1 && 's'}
                      </span>
                   </div>

                   <input 
                      type="range" 
                      min="0.5" 
                      max="10" 
                      step="0.5" 
                      value={customQuantity}
                      onChange={(e) => setCustomQuantity(parseFloat(e.target.value))}
                      className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-emerald-600 mb-4"
                   />

                   <div className="flex justify-between text-xs text-gray-400">
                      <span>0.5 {displayUnit}</span>
                      <span>5 {displayUnit}s</span>
                      <span>10 {displayUnit}s</span>
                   </div>

                   <div className="mt-4 pt-4 border-t border-gray-200 dark:border-gray-700 flex justify-between items-center">
                      <div className="flex flex-col">
                         <span className="text-xs text-gray-500">Estimated Price</span>
                         <span className="font-bold text-lg text-gray-900 dark:text-white">${customPrice.toFixed(2)}</span>
                      </div>
                      <div className="flex items-center gap-1 text-emerald-600 dark:text-emerald-400 text-xs font-bold bg-emerald-100 dark:bg-emerald-900/30 px-2 py-1 rounded">
                         <Check className="w-3 h-3" /> Available
                      </div>
                   </div>
                </div>
              )}
            </div>

            {/* Highlights */}
            <div className="mt-auto">
                <h3 className="font-bold text-gray-900 dark:text-white mb-4 text-sm uppercase tracking-wide">Highlights</h3>
                <div className="flex flex-wrap gap-3">
                    {product.highlights && product.highlights.length > 0 ? (
                        product.highlights.map((highlight, idx) => (
                            <span key={idx} className="bg-gray-100 dark:bg-gray-700/50 text-gray-600 dark:text-gray-300 px-4 py-2 rounded-full text-xs font-semibold border border-gray-200 dark:border-gray-600">
                                {highlight}
                            </span>
                        ))
                    ) : (
                        <span className="text-xs text-gray-400 italic">No highlights available</span>
                    )}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default ProductDetailsModal;

export enum Category {
  FRUITS = 'Fresh Fruit',
  VEGETABLES = 'Vegetables',
  DAIRY = 'Dairy & Eggs',
  BAKERY = 'Bakery',
  SNACKS = 'Snacks'
}

export interface Review {
  id: string;
  user: string;
  rating: number;
  comment: string;
  date: string;
}

export interface Product {
  id: string;
  name: string;
  price: number;
  category: string; 
  image: string;
  images?: string[];
  unit: string;
  description?: string;
  inStock: boolean;
  rating?: number;
  badge?: string; // e.g., "Fresh", "New", "Sale"
  isHotDeal?: boolean;
  salePrice?: number;
  highlights?: string[];
  reviews?: Review[];
}

export interface CartItem extends Product {
  quantity: number;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  isThinking?: boolean;
}

export type SortOption = 'featured' | 'price-asc' | 'price-desc' | 'name-asc';

export interface Order {
  id: string;
  date: string;
  total: number;
  status: 'Delivered' | 'Processing' | 'Cancelled';
  items: number;
}

export interface User {
  id: string;
  name: string;
  role: 'user' | 'admin';
  email: string;
  phone?: string;
  password?: string;
  savedAddresses?: string[];
  orders?: Order[];
  profileImage?: string;
