      <div
        className={`fixed inset-y-0 right-0 z-[60] w-full sm:w-[480px] bg-white dark:bg-gray-900 shadow-2xl transform transition-transform duration-300 ease-out flex flex-col ${
          isOpen ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
          {/* Header */}
          <div className="p-6 border-b border-gray-100 dark:border-gray-800 bg-white dark:bg-gray-900 z-10 flex flex-col gap-4 shadow-sm">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                    Your Cart 
                    <span className="text-base font-normal text-gray-500 dark:text-gray-400 bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded-full">
                        {items.length}
                    </span>
                </h2>
                <button
                    onClick={onClose}
                    className="p-2 bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors text-gray-600 dark:text-gray-300"
                >
                    <X className="w-5 h-5" />
                </button>
            </div>

            {/* Free Shipping Progress */}
            {items.length > 0 && (
                <div className="bg-emerald-50 dark:bg-emerald-900/10 rounded-xl p-4 border border-emerald-100 dark:border-emerald-900/30">
                   <div className="flex items-center gap-2 mb-2 text-sm">
                      <Truck className="w-4 h-4 text-emerald-600 dark:text-emerald-400" />
                      {remainingForFreeShipping > 0 ? (
                          <span className="text-gray-700 dark:text-gray-300">
                             Add <span className="font-bold text-emerald-600 dark:text-emerald-400">${remainingForFreeShipping.toFixed(2)}</span> for <span className="font-bold text-emerald-600 dark:text-emerald-400">Free Shipping</span>
                          </span>
                      ) : (
                          <span className="text-emerald-700 dark:text-emerald-400 font-bold">
                             🎉 You've unlocked Free Shipping!
                          </span>
                      )}
                   </div>
                   <div className="h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                      <div 
                        className="h-full bg-emerald-500 rounded-full transition-all duration-500 ease-out relative"
                        style={{ width: `${progressPercent}%` }}
                      >
                         <div className="absolute inset-0 bg-white/20 animate-pulse"></div>
                      </div>
                   </div>
                </div>
            )}
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {items.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center text-gray-400 dark:text-gray-500 space-y-6 animate-in fade-in zoom-in duration-300">
                <div className="w-24 h-24 bg-gray-50 dark:bg-gray-800 rounded-full flex items-center justify-center mb-4 relative">
                    <ShoppingBag className="w-10 h-10 opacity-30" />
                    <div className="absolute -top-1 -right-1 w-6 h-6 bg-yellow-400 rounded-full animate-bounce"></div>
                </div>
                <div>
                    <p className="text-xl font-bold text-gray-800 dark:text-gray-200 mb-2">Your cart is empty</p>
                    <p className="text-sm max-w-[200px] mx-auto">Looks like you haven't added anything yet. Explore our fresh categories!</p>
                </div>
                <button 
                  onClick={onClose}
                  className="px-8 py-3 bg-[#155e37] text-white rounded-xl font-bold text-sm hover:bg-emerald-800 transition-colors shadow-lg shadow-emerald-900/20"
                >
                  Start Shopping
                </button>
              </div>
            ) : (
                <>
                  <div className="space-y-4">
                    {items.map((item) => (
                        <div key={item.id} className="group flex gap-4 p-3 rounded-2xl bg-white dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-750 border border-gray-100 dark:border-gray-700 transition-all hover:shadow-md">
                        <div className="w-20 h-20 bg-gray-50 dark:bg-gray-700 rounded-xl overflow-hidden flex-shrink-0 border border-gray-100 dark:border-gray-600 relative">
                            <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
                        </div>
                        <div className="flex-1 flex flex-col justify-between py-1">
                            <div className="flex justify-between items-start">
                                <div>
                                <h3 className="font-bold text-gray-800 dark:text-gray-100 line-clamp-1">{item.name}</h3>
                                <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">${item.price.toFixed(2)} / {item.unit}</p>
                                </div>
                                <button 
                                    onClick={() => onRemoveItem(item.id)}
                                    className="text-gray-400 hover:text-red-500 transition-colors p-1 opacity-0 group-hover:opacity-100"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                            <div className="flex items-center justify-between mt-2">
                            <div className="flex items-center gap-3 bg-gray-50 dark:bg-gray-700/50 rounded-lg p-1 border border-gray-200 dark:border-gray-600">
                                <button
                                onClick={() => onUpdateQuantity(item.id, -1)}
                                className="w-6 h-6 flex items-center justify-center bg-white dark:bg-gray-600 rounded shadow-sm hover:text-red-500 transition-colors"
                                title={item.quantity === 1 ? "Remove item" : "Decrease quantity"}
                                >
                                {item.quantity === 1 ? <Trash2 className="w-3 h-3 text-red-500" /> : <Minus className="w-3 h-3" />}
                                </button>
                                <span className="text-sm font-bold w-4 text-center text-gray-700 dark:text-gray-200">{item.quantity}</span>
                                <button
                                onClick={() => onUpdateQuantity(item.id, 1)}
                                className="w-6 h-6 flex items-center justify-center bg-white dark:bg-gray-600 rounded shadow-sm hover:text-emerald-600 transition-colors"
                                >
                                <Plus className="w-3 h-3" />
                                </button>
                            </div>
                            <div className="text-right">
                                <span className="font-bold text-gray-900 dark:text-white block">
                                    ${(item.price * item.quantity).toFixed(2)}
                                </span>
                                <span className="text-[10px] text-gray-500 dark:text-gray-400 font-medium">
                                    Qty: {item.quantity}
                                </span>
                            </div>
                            </div>
                        </div>
                        </div>
                    ))}
                  </div>

                  {/* Smart Upsell Section */}
                  <div className="mt-8 pt-6 border-t border-gray-100 dark:border-gray-800">
                     <h3 className="text-sm font-bold text-gray-900 dark:text-gray-200 mb-4 flex items-center gap-2">
                        <Gift className="w-4 h-4 text-yellow-500" /> You might also like
                     </h3>
                     <div className="grid grid-cols-3 gap-3">
                         {suggestedProducts.map(p => (
                             <div key={p.id} className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl p-2 flex flex-col gap-2 hover:shadow-md transition-shadow group cursor-pointer" onClick={(e) => onAddToCart(p, 1, e)}>
                                 <div className="aspect-square rounded-lg bg-gray-50 dark:bg-gray-700 overflow-hidden relative">
                                    <img src={p.image} className="w-full h-full object-cover" alt={p.name} />
                                    <button className="absolute bottom-1 right-1 bg-white dark:bg-gray-800 rounded-full p-1 shadow-sm opacity-0 group-hover:opacity-100 transition-opacity">
                                        <Plus className="w-3 h-3 text-emerald-600" />
                                    </button>
                                 </div>
                                 <div>
                                     <p className="text-xs font-medium text-gray-800 dark:text-gray-200 truncate">{p.name}</p>
                                     <p className="text-xs text-gray-500 dark:text-gray-400">${p.price}</p>
                                 </div>
                             </div>
                         ))}
                     </div>
                  </div>
                </>
            )}
          </div>

          {items.length > 0 && (
            <div className="p-6 bg-white dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800 shadow-[0_-4px_20px_-5px_rgba(0,0,0,0.05)] z-20">
               {/* Promo Code Input */}
               <div className="flex gap-2 mb-6">
                   <div className="relative flex-1">
                      <Tag className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                      <input 
                        type="text" 
                        placeholder="Promo Code" 
                        value={promoCode}
                        onChange={(e) => setPromoCode(e.target.value)}
                        className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl py-2.5 pl-10 pr-4 text-sm outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 transition-all"
                      />
                   </div>
                   <button className="bg-gray-900 dark:bg-gray-700 text-white px-4 rounded-xl text-sm font-bold hover:bg-gray-800 transition-colors">
                       Apply
                   </button>
               </div>

              <div className="space-y-3 mb-6">
                 <div className="flex justify-between items-center text-gray-500 dark:text-gray-400 text-sm">
                    <span>Subtotal</span>
                    <span>${total.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between items-center text-gray-500 dark:text-gray-400 text-sm">
                    <span>Shipping</span>
                    {total >= freeShippingThreshold ? (
                        <span className="text-emerald-600 dark:text-emerald-400 font-medium">Free</span>
                    ) : (
                        <span>$5.00</span>
                    )}
                 </div>
                 <div className="h-px bg-gray-100 dark:bg-gray-800 my-2"></div>
                 <div className="flex justify-between items-center">
                    <span className="font-bold text-gray-800 dark:text-gray-100 text-lg">Total</span>
                    <span className="text-2xl font-bold text-emerald-700 dark:text-emerald-400">
                        ${(total + (total >= freeShippingThreshold ? 0 : 5)).toFixed(2)}
                    </span>
                 </div>
              </div>
              <button className="group w-full py-4 bg-[#155e37] text-white rounded-xl font-bold text-lg hover:bg-emerald-800 active:transform active:scale-[0.98] transition-all shadow-xl shadow-emerald-900/20 flex items-center justify-center gap-2">
                Checkout Now <ChevronRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
              </button>
            </div>
          )}
      </div>
    </>
  );
}

import React, { useState } from 'react';
import { X, Package, Trash2, Plus, DollarSign, Users, BarChart3, Upload, Search, ArrowRight, Layout, Image as ImageIcon, UserPlus, Flame, Settings as SettingsIcon, Tag } from 'lucide-react';
import { Product, HeroSlide, SideBanner, User } from '../types';

interface AdminDashboardProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onRemoveProduct: (id: string) => void;
  users: User[];
  onAddUser: (user: User) => void;
  onRemoveUser: (id: string) => void;
  heroSlides: HeroSlide[];
  onUpdateHero: (slides: HeroSlide[]) => void;
  categories: string[];
  onAddCategory: (category: string) => void;
  sideBanners?: SideBanner[];
  onUpdateSideBanners?: (banners: SideBanner[]) => void;
  // New props for store settings
  storeName?: string;
  storeLogo?: string;
  onUpdateStoreSettings?: (name: string, logo: string) => void;
  // New props for Hot Deals
  onUpdateProduct?: (product: Product) => void;
}

const UNIVERSAL_UNITS = [
  'kg', 'g', 'lb', 'oz', 
  'L', 'ml', 'gallon', 
  'pack', 'bunch', 'dozen', 
  'tin', 'jar', 'bottle', 'can', 'pc'
];

export default function AdminDashboard({ 
    isOpen, 
    onClose, 
    products, 
    onAddProduct, 
    onRemoveProduct, 
    users,
    onAddUser,
    onRemoveUser,
    heroSlides,
    onUpdateHero,
    categories,
    onAddCategory,
    sideBanners,
    onUpdateSideBanners,
    storeName = "H Mart",
    storeLogo = "",
    onUpdateStoreSettings,
    onUpdateProduct
}: AdminDashboardProps) {
  const [activeTab, setActiveTab] = useState<'overview' | 'products' | 'users' | 'hero' | 'categories' | 'settings' | 'hot-deals'>('overview');
  const [isAddMode, setIsAddMode] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Store Settings State
  const [settingsName, setSettingsName] = useState(storeName);
  const [settingsLogo, setSettingsLogo] = useState(storeLogo);

  // Product View State
  const [productViewMode, setProductViewMode] = useState<'categories' | 'list'>('categories');
  const [selectedAdminCategory, setSelectedAdminCategory] = useState<string>('');

  // New Product Form State
  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '',
    price: 0,
    category: categories[0],
    unit: 'kg',
    image: '',
    images: [],
    description: '',
    inStock: true,
    badge: 'Fresh',
    highlights: []
  });
  const [highlightsInput, setHighlightsInput] = useState('');

  const [newUser, setNewUser] = useState({
      username: '',
      password: '',
      email: ''
  });

  const [newCategory, setNewCategory] = useState('');
  const [editingSlides, setEditingSlides] = useState<HeroSlide[]>(heroSlides);
  const [editingSideBanners, setEditingSideBanners] = useState<SideBanner[]>(sideBanners || []);

  if (!isOpen) return null;

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      Promise.all(files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      })).then(base64Images => {
        setNewProduct(prev => ({
            ...prev,
            image: prev.image || base64Images[0], 
            images: [...(prev.images || []), ...base64Images]
        }));
      });
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if(e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const reader = new FileReader();
          reader.onloadend = () => setSettingsLogo(reader.result as string);
          reader.readAsDataURL(file);
      }
  };

  const removeImage = (indexToRemove: number) => {
    setNewProduct(prev => {
      const updatedImages = (prev.images || []).filter((_, idx) => idx !== indexToRemove);
      return {
        ...prev,
        images: updatedImages,
        image: updatedImages[0] || ''
      };
    });
  };

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newProduct.name && newProduct.price && newProduct.image) {
      onAddProduct({
        id: Date.now().toString(),
        name: newProduct.name,
        price: Number(newProduct.price),
        category: newProduct.category || categories[0],
        unit: newProduct.unit || 'kg',
        image: newProduct.image,
        images: newProduct.images,
        description: newProduct.description || 'Fresh item added by admin.',
        inStock: true,
        badge: newProduct.badge || '',
        highlights: highlightsInput.split(',').map(h => h.trim()).filter(Boolean)
      });
      setIsAddMode(false);
      setNewProduct({
        name: '', price: 0, category: categories[0], unit: 'kg', image: '', images: [], description: '', inStock: true, badge: 'Fresh', highlights: []
      });
      setHighlightsInput('');
    }
  };

  const handleSaveSettings = () => {
      if(onUpdateStoreSettings) {
          onUpdateStoreSettings(settingsName, settingsLogo);
          alert("Store settings saved!");
      }
  };

  const toggleHotDeal = (product: Product) => {
      if (onUpdateProduct) {
          onUpdateProduct({
              ...product,
              isHotDeal: !product.isHotDeal,
              salePrice: !product.isHotDeal ? Number((product.price * 0.8).toFixed(2)) : undefined
          });
      }
  };

  const updateSalePrice = (product: Product, newPrice: number) => {
      if (onUpdateProduct) {
          onUpdateProduct({
              ...product,
              salePrice: newPrice
          });
      }
  };

  const filteredProducts = products.filter(p => {
    const matchesCategory = selectedAdminCategory ? p.category === selectedAdminCategory : true;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 font-sans">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-900 rounded-2xl w-full max-w-6xl h-[90vh] shadow-2xl overflow-hidden flex flex-col md:flex-row animate-in fade-in zoom-in-95 duration-200">

        {/* Sidebar */}
        <div className="w-full md:w-64 bg-gray-50 dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 flex flex-col">
            <div className="p-6 border-b border-gray-200 dark:border-gray-700">
                <h2 className="font-black text-xl text-[#155e37] dark:text-emerald-400 flex items-center gap-2">
                    <BarChart3 className="w-6 h-6" /> Admin
                </h2>
            </div>
            <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
                <button onClick={() => setActiveTab('overview')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'overview' ? 'bg-emerald-100 text-emerald-700' : 'text-gray-600 hover:bg-gray-100'}`}><BarChart3 className="w-5 h-5" /> Overview</button>
                <button onClick={() => { setActiveTab('products'); setProductViewMode('categories'); }} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'products' ? 'bg-emerald-100 text-emerald-700' : 'text-gray-600 hover:bg-gray-100'}`}><Package className="w-5 h-5" /> Products</button>
                <button onClick={() => setActiveTab('hot-deals')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'hot-deals' ? 'bg-emerald-100 text-emerald-700' : 'text-gray-600 hover:bg-gray-100'}`}><Flame className="w-5 h-5" /> Hot Deals</button>
                <button onClick={() => setActiveTab('categories')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'categories' ? 'bg-emerald-100 text-emerald-700' : 'text-gray-600 hover:bg-gray-100'}`}><Layout className="w-5 h-5" /> Categories</button>
                <button onClick={() => setActiveTab('users')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'users' ? 'bg-emerald-100 text-emerald-700' : 'text-gray-600 hover:bg-gray-100'}`}><Users className="w-5 h-5" /> Users</button>
                <button onClick={() => setActiveTab('hero')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'hero' ? 'bg-emerald-100 text-emerald-700' : 'text-gray-600 hover:bg-gray-100'}`}><ImageIcon className="w-5 h-5" /> Hero & Banners</button>
                <button onClick={() => setActiveTab('settings')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === 'settings' ? 'bg-emerald-100 text-emerald-700' : 'text-gray-600 hover:bg-gray-100'}`}><SettingsIcon className="w-5 h-5" /> Store Settings</button>
            </nav>
            <div className="p-4 border-t border-gray-200 dark:border-gray-700">
                 <button onClick={onClose} className="w-full py-2 text-sm font-bold text-gray-500 hover:text-gray-800 transition-colors">Exit Dashboard</button>
            </div>
        </div>

        {/* Main Content */}
        <div className="flex-1 flex flex-col overflow-hidden bg-white dark:bg-gray-900">
            <div className="p-6 border-b border-gray-100 dark:border-gray-800 flex justify-between items-center bg-white dark:bg-gray-900 sticky top-0 z-10">
                <h3 className="text-2xl font-bold text-gray-900 dark:text-white capitalize">{activeTab.replace('-', ' ')}</h3>
            </div>

            <div className="flex-1 overflow-y-auto p-6">
                {activeTab === 'overview' && (
                    <div className="space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div className="bg-blue-50 dark:bg-blue-900/10 p-6 rounded-2xl border border-blue-100 dark:border-blue-800">
                                <p className="text-gray-500 text-sm font-medium">Total Revenue</p>
                                <h4 className="text-2xl font-black text-gray-900 dark:text-white">$24,500.00</h4>
                            </div>
                            <div className="bg-orange-50 dark:bg-orange-900/10 p-6 rounded-2xl border border-orange-100 dark:border-orange-800">
                                <p className="text-gray-500 text-sm font-medium">Total Users</p>
                                <h4 className="text-2xl font-black text-gray-900 dark:text-white">{users.length}</h4>
                            </div>
                            <div className="bg-purple-50 dark:bg-purple-900/10 p-6 rounded-2xl border border-purple-100 dark:border-purple-800">
                                <p className="text-gray-500 text-sm font-medium">Total Products</p>
                                <h4 className="text-2xl font-black text-gray-900 dark:text-white">{products.length}</h4>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'settings' && (
                    <div className="max-w-xl">
                        <h4 className="font-bold text-lg mb-4">Store Identity</h4>
                        <div className="space-y-6">
                            <div>
                                <label className="block text-sm font-bold mb-2">Store Name</label>
                                <input type="text" className="w-full p-3 border rounded-xl" value={settingsName} onChange={(e) => setSettingsName(e.target.value)} />
                            </div>
                            <div>
                                <label className="block text-sm font-bold mb-2">Store Logo (Square recommended)</label>
                                <div className="flex items-center gap-4">
                                    <div className="w-20 h-20 bg-gray-100 rounded-xl flex items-center justify-center overflow-hidden border">
                                        {settingsLogo ? <img src={settingsLogo} alt="Logo" className="w-full h-full object-cover" /> : <ImageIcon className="text-gray-400" />}
                                    </div>
                                    <label className="bg-gray-100 hover:bg-gray-200 px-4 py-2 rounded-lg cursor-pointer text-sm font-bold">
                                        Upload Logo <input type="file" accept="image/*" className="hidden" onChange={handleLogoUpload} />
                                    </label>
                                </div>
                            </div>
                            <button onClick={handleSaveSettings} className="bg-emerald-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-emerald-700">Save Changes</button>
                        </div>
                    </div>
                )}

                {activeTab === 'hot-deals' && (
                    <div className="space-y-6">
                        <div className="bg-amber-50 border border-amber-200 p-4 rounded-xl text-amber-800 text-sm flex items-center gap-2">
                             <Flame className="w-5 h-5" /> Manage products in the "Hot Offers" section. Set a sale price to activate the discount badge.
                        </div>
                        <div className="space-y-2">
                            {products.map(product => (
                                <div key={product.id} className="flex items-center justify-between p-4 bg-white border rounded-xl hover:shadow-sm">
                                    <div className="flex items-center gap-3">
                                        <img src={product.image} className="w-12 h-12 rounded-lg object-cover" alt="" />
                                        <div>
                                            <p className="font-bold text-sm">{product.name}</p>
                                            <p className="text-xs text-gray-500">${product.price}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-4">
                                        {product.isHotDeal && (
                                            <div className="flex items-center gap-2">
                                                <span className="text-xs font-bold">Sale Price:</span>
                                                <input 
                                                    type="number" 
                                                    className="w-24 p-1 border rounded text-sm"
                                                    value={product.salePrice}
                                                    onChange={(e) => updateSalePrice(product, parseFloat(e.target.value))}
                                                />
                                            </div>
                                        )}
                                        <button 
                                            onClick={() => toggleHotDeal(product)}
                                            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${product.isHotDeal ? 'bg-red-100 text-red-600 border border-red-200' : 'bg-gray-100 text-gray-600'}`}
                                        >
                                            {product.isHotDeal ? 'Active Deal' : 'Add to Deals'}
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* PRODUCT MANAGEMENT LOGIC */}
                {activeTab === 'products' && !isAddMode && productViewMode === 'categories' && (
                    <div className="space-y-6">
                         <div className="flex justify-between items-center">
                            <h3 className="font-bold text-lg">Select Category</h3>
                            <button onClick={() => setIsAddMode(true)} className="bg-emerald-600 text-white px-4 py-2 rounded-xl font-bold flex items-center gap-2"><Plus className="w-4 h-4" /> Add Product</button>
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            {categories.map((cat, idx) => (
                                <div key={idx} onClick={() => { setSelectedAdminCategory(cat); setProductViewMode('list'); }} className="bg-white p-6 rounded-2xl border hover:border-emerald-500 cursor-pointer transition-all">
                                    <h4 className="font-bold">{cat}</h4>
                                    <p className="text-xs text-gray-500">{products.filter(p => p.category === cat).length} Items</p>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {activeTab === 'products' && !isAddMode && productViewMode === 'list' && (
                    <div className="space-y-4">
                        <button onClick={() => setProductViewMode('categories')} className="text-sm font-bold text-gray-500 flex items-center gap-2"><ArrowRight className="w-4 h-4 rotate-180" /> Back</button>
                        <h3 className="font-bold text-xl">{selectedAdminCategory}</h3>
                        <table className="w-full text-left bg-white rounded-xl overflow-hidden shadow-sm border">
                            <thead className="bg-gray-50 text-xs uppercase font-bold text-gray-500">
                                <tr>
                                    <th className="p-4">Product</th>
                                    <th className="p-4">Price</th>
                                    <th className="p-4">Badge</th>
                                    <th className="p-4 text-right">Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredProducts.map(p => (
                                    <tr key={p.id} className="border-t">
                                        <td className="p-4 flex items-center gap-3">
                                            <img src={p.image} className="w-10 h-10 rounded object-cover" alt="" />
                                            <span className="font-bold text-sm">{p.name}</span>
                                        </td>
                                        <td className="p-4">${p.price}</td>
                                        <td className="p-4"><span className="text-xs bg-gray-100 px-2 py-1 rounded">{p.badge || '-'}</span></td>
                                        <td className="p-4 text-right"><button onClick={() => onRemoveProduct(p.id)} className="text-red-500 hover:bg-red-50 p-2 rounded"><Trash2 className="w-4 h-4" /></button></td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {isAddMode && (
                     <div className="max-w-2xl mx-auto">
                        <button onClick={() => setIsAddMode(false)} className="mb-4 text-sm font-bold text-gray-500">Cancel</button>
