                                <div className="grid grid-cols-2 gap-4">
                                    <div><label className="text-xs font-bold uppercase block mb-1">Price</label><input type="number" className="w-full p-2 border rounded-lg" value={newProduct.price} onChange={e => setNewProduct({...newProduct, price: parseFloat(e.target.value)})} /></div>
