                        onClick={() => setBankDiscountActive(!bankDiscountActive)}
                    >
                       <div className={`mt-0.5 w-5 h-5 rounded-md border-2 flex items-center justify-center transition-colors ${bankDiscountActive ? 'bg-emerald-500 border-emerald-500' : 'border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800'}`}>
                           {bankDiscountActive && <Check className="w-3 h-3 text-white" />}
