                       </div>
                    </div>
                    <div className="h-px bg-gray-100 dark:bg-gray-700 mx-2"></div>
                    <div 
                        className={`flex gap-3 items-start cursor-pointer p-3 rounded-xl transition-all border ${specialDiscountActive ? 'bg-emerald-50 dark:bg-emerald-900/10 border-emerald-200 dark:border-emerald-800' : 'border-transparent hover:bg-gray-50 dark:hover:bg-gray-700'}`} 
                        onClick={() => setSpecialDiscountActive(!specialDiscountActive)}
                    >
                       <div className={`mt-0.5 w-5 h-5 rounded-md border-2 flex items-center justify-center transition-colors ${specialDiscountActive ? 'bg-emerald-500 border-emerald-500' : 'border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800'}`}>
