                       </div>
                       <div>
                          <p className="text-sm font-bold text-gray-800 dark:text-gray-200">Special Price (5%)</p>
                          <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">Get extra 5% off (price inclusive of cashback)</p>
                       </div>
                    </div>
                 </div>
               )}
            </div>

            {/* Selection Tabs */}
            <div className="bg-gray-100 dark:bg-gray-700/50 p-1 rounded-xl flex mb-6">
               <button 
                 onClick={() => setActiveTab('packs')}
                 className={`flex-1 py-2.5 px-4 text-sm font-bold rounded-lg transition-all ${activeTab === 'packs' ? 'bg-white dark:bg-gray-800 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
               >
                 Pack Sizes
               </button>
               <button 
                 onClick={() => setActiveTab('custom')}
                 className={`flex-1 py-2.5 px-4 text-sm font-bold rounded-lg transition-all flex items-center justify-center gap-2 ${activeTab === 'custom' ? 'bg-white dark:bg-gray-800 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
               >
                 <SlidersHorizontal className="w-3 h-3" /> Custom Size
               </button>
            </div>

            {/* Pack Size / Custom Selection */}
            <div className="mb-8">
              {activeTab === 'packs' ? (
                <div className="space-y-3">
                    {packOptions.map((option, idx) => (
                        <div 
                            key={idx}
                            onClick={() => setSelectedPack(idx)}
                            className={`relative border-2 rounded-xl p-4 cursor-pointer flex justify-between items-center transition-all group ${
                                selectedPack === idx 
                                ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/10 shadow-sm' 
                                : 'border-gray-100 dark:border-gray-700 hover:border-emerald-200 dark:hover:border-emerald-800'
                            }`}
                        >
                            <div className="flex flex-col">
                                <span className="font-bold text-gray-900 dark:text-white mb-1">{option.size}</span>
                                <div className="flex items-center gap-2">
                                    <span className="text-sm font-medium text-gray-600 dark:text-gray-300">${option.price.toFixed(2)}</span>
                                    <span className="text-xs text-gray-400 line-through">${option.mrp.toFixed(2)}</span>
                                </div>
                            </div>

                            <div className="flex items-center gap-3">
                                <span className="text-xs font-bold text-emerald-700 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-900/30 px-2 py-1 rounded-md">
                                    {Math.round(option.discount)}% OFF
                                </span>
                                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors ${selectedPack === idx ? 'border-emerald-500 bg-emerald-500 text-white' : 'border-gray-300 dark:border-gray-600'}`}>
                                    {selectedPack === idx && <Check className="w-3.5 h-3.5" />}
