      <div className="relative bg-white dark:bg-gray-800 rounded-3xl shadow-2xl w-full max-w-6xl max-h-[95vh] overflow-y-auto flex flex-col md:flex-row animate-in fade-in zoom-in-95 duration-200 border border-gray-200 dark:border-gray-700">

        {/* Close Button */}
