               >
                 Pack Sizes
               </button>
               <button 
                 onClick={() => setActiveTab('custom')}
                 className={`flex-1 py-2 px-3 text-xs font-bold rounded-lg transition-all flex items-center justify-center gap-2 ${activeTab === 'custom' ? 'bg-white dark:bg-gray-800 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
               >
                 <SlidersHorizontal className="w-3 h-3" /> Custom Size
               </button>
            </div>

            {/* Pack Size / Custom Selection */}
            <div className="mb-6 flex-1">
              {activeTab === 'packs' ? (
                <div className="space-y-2">
                    {packOptions.map((option, idx) => (
                        <div 
                            key={idx}
                            onClick={() => setSelectedPack(idx)}
                            className={`relative border-2 rounded-xl p-3 cursor-pointer flex justify-between items-center transition-all group ${
