                                ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/10 shadow-sm' 
                                : 'border-gray-100 dark:border-gray-700 hover:border-emerald-200 dark:hover:border-emerald-800'
                            }`}
                        >
                            <div className="flex flex-col">
                                <span className="font-bold text-sm text-gray-900 dark:text-white mb-0.5">{option.size}</span>
                                <div className="flex items-center gap-2">
                                    <span className="text-xs font-medium text-gray-600 dark:text-gray-300">${option.price.toFixed(2)}</span>
                                    <span className="text-[10px] text-gray-400 line-through">${option.mrp.toFixed(2)}</span>
                                </div>
                            </div>

                            <div className="flex items-center gap-3">
                                <span className="text-[10px] font-bold text-emerald-700 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-900/30 px-1.5 py-0.5 rounded-md">
                                    {Math.round(option.discount)}% OFF
                                </span>
                                <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-colors ${selectedPack === idx ? 'border-emerald-500 bg-emerald-500 text-white' : 'border-gray-300 dark:border-gray-600'}`}>
                                    {selectedPack === idx && <Check className="w-3 h-3" />}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
              ) : (
                <div className="bg-gray-50 dark:bg-gray-900/50 rounded-2xl p-5 border border-gray-100 dark:border-gray-700">
