                      <span className="text-xl font-black text-emerald-600 dark:text-emerald-400">
                        {customQuantity} <span className="text-sm font-normal text-gray-500 dark:text-gray-400">{displayUnit}{customQuantity > 1 && 's'}</span>
                      </span>
                   </div>

                   <div className="relative mb-6">
                       <input 
                          type="range" 
                          min={minQuantity}
                          max="10" 
                          step={quantityStep}
                          value={customQuantity}
                          onChange={(e) => setCustomQuantity(parseFloat(e.target.value))}
                          className="w-full h-2 bg-gray-200 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-emerald-600"
                       />
                       <div className="flex justify-between text-[10px] font-bold text-gray-400 mt-2">
                          <span>{minQuantity}</span>
                          <span>5</span>
                          <span>10</span>
                       </div>
                   </div>

                   <div className="bg-white dark:bg-gray-800 p-3 rounded-xl flex justify-between items-center shadow-sm">
                      <div className="flex flex-col">
                         <span className="text-[10px] font-bold text-gray-400 uppercase">Estimated Price</span>
                         <span className="font-black text-lg text-gray-900 dark:text-white">${customPrice.toFixed(2)}</span>
                      </div>
                      <div className="flex items-center gap-1.5 text-emerald-600 dark:text-emerald-400 text-[10px] font-bold bg-emerald-50 dark:bg-emerald-900/20 px-2 py-1 rounded-full border border-emerald-100 dark:border-emerald-900/30">
                         <Check className="w-2.5 h-2.5" /> In Stock
                      </div>
                   </div>
                </div>
              )}
            </div>

            {/* Actions */}
            <div className="mt-auto">
                <button
                    onClick={(e) => onAddToCart(product, currentQuantity, e)}
                    disabled={!product.inStock}
                    className="w-full bg-[#da251d] hover:bg-[#b01e17] text-white font-black py-4 px-6 rounded-2xl shadow-lg hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed uppercase text-sm tracking-widest transform hover:-translate-y-1 active:scale-[0.98] flex items-center justify-center gap-3"
                >
                    <span>Add to Basket</span>
                    <span className="bg-white/20 px-2 py-0.5 rounded text-white text-xs font-bold">
                        ${currentPrice.toFixed(2)}
                    </span>
                </button>
            </div>

            {/* Highlights */}
            <div className="mt-6 pt-5 border-t border-gray-100 dark:border-gray-700">
                <h3 className="font-bold text-gray-400 dark:text-gray-500 mb-2 text-[10px] uppercase tracking-widest">Product Highlights</h3>
                <div className="flex flex-wrap gap-2">
                    {product.highlights && product.highlights.length > 0 ? (
                        product.highlights.map((highlight, idx) => (
                            <span key={idx} className="bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300 px-2.5 py-1 rounded-lg text-[10px] font-bold border border-gray-100 dark:border-gray-700 shadow-sm">
