// Animation Component - Slowed Down
const FlyingItem: React.FC<{ src: string, start: {x: number, y: number}, end: {x: number, y: number}, onComplete: () => void }> = ({ src, start, end, onComplete }) => {
  const [style, setStyle] = useState<React.CSSProperties>({
    position: 'fixed',
    top: start.y,
    left: start.x,
    width: '50px',
    height: '50px',
    borderRadius: '50%',
    backgroundImage: `url(${src})`,
    backgroundSize: 'cover',
    zIndex: 9999,
    pointerEvents: 'none',
    transition: 'all 1.5s cubic-bezier(0.25, 0.46, 0.45, 0.94)', // Slower, smoother bezier
    transform: 'translate(-50%, -50%) scale(1)',
    opacity: 0.9,
    boxShadow: '0 4px 20px rgba(0,0,0,0.3)'
  });

  useEffect(() => {
    // Trigger animation next frame
    requestAnimationFrame(() => {
      setStyle(prev => ({
        ...prev,
        top: end.y,
        left: end.x,
        transform: 'translate(-50%, -50%) scale(0.1) rotate(360deg)',
        opacity: 0
      }));
    });

    const timer = setTimeout(onComplete, 1500); // Matches transition duration
    return () => clearTimeout(timer);
  }, [end, onComplete]);

  return <div style={style} />;
};

